(function(){
'use strict';
const D=globalThis.RA.D;
const q=(prompt,answer,d1,d2,explain,sense=1,type='meaning')=>({prompt,answer,d1,d2,explain,sense,type});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((x,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+x.sense,type:'辨义与用法',prompt:x.prompt,options:[x.answer,x.d1,x.d2],answer:x.answer,explain:x.explain,errorType:x.type}))});
P('stagehand','Stagehand combines stage and hand; it means a theater worker who handles props, scenery, or backstage lights.',C('stagehand.s1','舞台工作人员','The stagehand rolled the painted street flat into position before the actors entered for the scene.','演员进场表演前，舞台工作人员把画好的街景布景推到位。','The stagehand rolled the painted flat / into position / before the actors entered.','stagehand.s1 指在幕后搬动道具、布景或灯光设备的剧场工作人员。','他在演员进场前布置景片。'),M('The stagehand delivered the lead role onstage while another worker handled every prop backstage.','The worker who moved the scenery backstage was the stagehand.','台上扮演主角的是演员，不是负责后台工作的 stagehand。','meaning'),[q('What did the stagehand move?','the painted street flat','the audience seats','the actors’ written script','舞台工作人员把画好的街景布景推到位。',1,'context'),q('When did the worker place the scenery?','before the actors entered','after the audience went home','during the ticket sale','布景在演员进场前就位。',1,'context'),q('What is a stagehand?','a backstage worker who handles scenery or props','the lead actor in a play','a person buying a theater ticket','stagehand 指负责布景、道具或灯光的后台人员。',1,'meaning'),q('Which task belongs to a stagehand?','setting a prop table before a performance','performing the lead role','reviewing the theater’s annual budget','演出前布置道具台属于 stagehand 的工作。',1,'context')]);
P('stagflation','Stagflation blends stagnation and inflation; it means a stagnant economy combined with rising prices and high unemployment.',C('stagflation.s1','滞胀','During stagflation, prices climbed while factories cut production and more workers searched for jobs.','滞胀期间物价上涨，工厂却削减产量，更多工人开始找工作。','During stagflation, prices climbed / while factories cut production / and unemployment rose.','stagflation.s1 指经济停滞、高失业与物价上涨同时出现的局面。','物价升而生产降、失业升。'),M('The country faced stagflation as prices fell, output boomed, and every job seeker found work immediately.','Prices rose while production stagnated and unemployment increased.','物价下跌、产量繁荣和充分就业并不符合 stagflation。','meaning'),[q('What happened to prices during stagflation?','they climbed','they fell steadily','they remained fixed by the theater','滞胀期间物价上涨。',1,'context'),q('What did factories do?','cut production','double output each week','move their stages backstage','工厂削减了产量。',1,'context'),q('What does stagflation combine?','economic stagnation and inflation','a theater stage and a job fair','low prices and full employment','stagflation 是经济停滞与通货膨胀并存。',1,'meaning'),q('Which situation is stagflation?','rising prices with weak growth and high unemployment','falling prices with booming production and full employment','a short-lived theater strike only','物价上涨、经济疲弱且失业高是 stagflation。',1,'meaning')]);
P('stagger','Stagger is recorded in Middle English; its deeper origin is uncertain. It can mean walk unsteadily, shock greatly, or arrange events at different times.',[C('stagger.s1','蹒跚；摇摇晃晃地走','The exhausted hiker staggered toward the ranger station, leaning on a walking stick after the steep climb.','筋疲力尽的徒步者爬完陡坡后拄着手杖，摇摇晃晃地走向护林站。','The hiker staggered toward the station / leaning on a stick / after the climb.','stagger.s1 指步伐不稳、仿佛快要跌倒地行走。','疲劳使步伐摇晃。'),C('stagger.s2','使震惊','The repair bill staggered the museum director because it cost three times the annual maintenance budget.','维修账单让博物馆馆长大吃一惊，因为费用是年度维护预算的三倍。','The repair bill staggered the director / because it was triple / the annual budget.','stagger.s2 作动词，指使人非常震惊。','账单金额远超预算。'),C('stagger.s3','使错开；错时安排','The clinic staggered appointments by fifteen minutes to keep the waiting room from becoming crowded.','诊所把预约时间错开十五分钟，避免候诊室过于拥挤。','The clinic staggered appointments / by fifteen minutes / to reduce crowding.','stagger.s3 指安排活动不要同时发生，而是错开时间。','预约按间隔时段安排。')],M('The tired hiker staggered toward camp by walking steadily with perfect balance after the climb.','The hiker walked unsteadily and leaned on a stick.','步伐平稳且平衡良好与 stagger 相反。','meaning'),[q('How did the hiker reach the ranger station?','unsteadily, leaning on a stick','running smoothly downhill','riding in a theater cart','徒步者拄着手杖摇晃着走向护林站。',1,'context'),q('Why was the director staggered by the bill?','it cost three times the annual budget','it was smaller than a single ticket','it arrived exactly on time','账单金额是维护预算的三倍。',2,'context'),q('How did the clinic stagger appointments?','by spacing them fifteen minutes apart','by scheduling every patient at once','by canceling all visits','诊所把预约时间错开十五分钟。',3,'context'),q('What does stagger mean in the hiking sentence?','walk with unsteady steps','arrange events at different times','make someone very surprised','徒步例句中的 stagger 指蹒跚行走。',1,'meaning')]);
P('staggered','Staggered is the past participle/adjective of stagger; it means so surprised that one can hardly react.',C('staggered.s1','大吃一惊的','Mina was staggered when the small grant turned out to be enough to restore the entire village library.','小额拨款竟足够修复整座村庄图书馆，米娜对此大吃一惊。','Mina was staggered / when the small grant / restored the whole library.','staggered.s1 指受到意外消息或结果强烈震惊、几乎不知如何反应。','结果远超她的预期。'),M('Mina was staggered by the grant and calmly expected exactly that amount all along.','The unexpected result left Mina deeply surprised.','早已平静预料的结果不会使人 staggered。','meaning'),[q('What surprised Mina?','the small grant could restore the whole library','the library was already new','the clinic staggered its appointments','拨款足以修复整座图书馆让米娜大吃一惊。',1,'context'),q('How large was the grant described as?','small','three times the annual budget','large enough for a new theater','这笔拨款原本很小。',1,'context'),q('What does staggered mean here?','so surprised that one can hardly react','walking with unsteady steps','scheduled at intervals','staggered 表示震惊得几乎无法反应。',1,'meaning'),q('Which person is staggered?','someone shocked by an outcome far beyond expectations','someone who calmly predicted the outcome exactly','someone assigning appointments every fifteen minutes','被远超预期的结果震惊的人是 staggered。',1,'context')]);
P('staggering','Staggering is formed from stagger and -ing; it can mean shockingly large in amount/size or so surprising it is hard to believe.',[C('staggering.s1','（数量等）惊人的；巨大的','The archive digitized a staggering two million pages in a single year with a small team.','档案馆用一支小团队在一年内数字化了惊人的两百万页。','The archive digitized a staggering two million pages / in one year / with a small team.','staggering.s1 指数量、规模大得令人震惊。','短时间内完成的页数极多。'),C('staggering.s2','令人震惊的','It was staggering news that the supposedly empty theater had been booked for every night of the season.','原以为空置的剧院竟已订满整个演出季，这消息令人震惊。','It was staggering news / that the theater was booked / every night of the season.','staggering.s2 指消息或事实令人难以置信、十分惊人。','剧院竟然全季订满。')],M('The archive digitized a staggering two pages in a full year with a huge team.','It digitized two million pages in one year using only a small team.','两页并非惊人的数量，且团队并不庞大。','meaning'),[q('How many pages did the archive digitize?','two million','two','two billion every hour','档案馆一年内数字化了两百万页。',1,'context'),q('How many nights was the theater booked?','every night of the season','only one night','no nights at all','剧院整个演出季每晚都有预约。',2,'context'),q('What does staggering mean about the page total?','shockingly large','very small and ordinary','scheduled at intervals','staggering 描述页数时指数量惊人。',1,'meaning'),q('Why was the theater report staggering?','the supposedly empty venue was booked all season','the archive digitized fewer than three pages','the theater had staggered its staff','剧院原本以为空置却全季订满，消息令人震惊。',2,'meaning')]);
P('stagnant','Stagnant comes from Latin stagnare, “stand still”; it can describe water/air that does not flow or an economy/career that fails to develop.',[C('stagnant.s1','（水、空气）不流动的','Mosquitoes gathered around stagnant water in an uncovered barrel behind the shed.','蚊子聚集在棚屋后一个敞口桶里的死水周围。','Mosquitoes gathered around stagnant water / in an uncovered barrel / behind the shed.','stagnant.s1 指不流动的水或空气，常因此变脏或发臭。','水长期静止，吸引蚊虫。'),C('stagnant.s2','停滞不前的','After years without training or promotion, his career felt stagnant despite his steady work.','多年没有培训或晋升后，尽管他一直勤奋工作，事业仍让人觉得停滞不前。','His career felt stagnant / after years without training / or promotion.','stagnant.s2 指经济、事业等没有增长或发展。','没有培训和晋升，事业缺乏发展。')],M('The stagnant pond flowed rapidly through a clean channel and never collected insects.','The water stood still and attracted mosquitoes.','快速流动的水不是 stagnant。','meaning'),[q('Where was the stagnant water?','in an uncovered barrel behind the shed','in a fast river channel','inside the theater archive','死水在棚屋后的敞口桶里。',1,'context'),q('Why did the career feel stagnant?','there had been no training or promotion for years','the worker was promoted every month','the job had just begun','多年没有培训或晋升，使事业停滞不前。',2,'context'),q('What does stagnant mean about water?','not flowing and often dirty or smelly','moving quickly through a channel','freshly filtered','stagnant 描述水时指不流动、可能发臭。',1,'meaning'),q('What does stagnant mean about a career?','not growing or developing','moving at a steady fast pace','shocked by surprising news','stagnant 描述事业时指缺乏发展。',2,'meaning')]);
P('stagnate','Stagnate comes from Latin stagnare, “stand still”; it can mean stop growing/developing or, of water, stop flowing and become dirty.',[C('stagnate.s1','停滞；不发展','Without new products or customers, the small company began to stagnate after its early growth.','没有新产品或客户，这家小公司在早期增长后开始停滞。','The company began to stagnate / without new products / or customers.','stagnate.s1 指发展、增长或进步停止。','缺少创新和客户导致公司停滞。'),C('stagnate.s2','（水）不流动；变污浊','If rainwater is allowed to stagnate in the old basin, it will become dirty and attract insects.','如果任由雨水在旧水池里停滞，就会变脏并招来昆虫。','Rainwater will stagnate in the old basin / and become dirty / if left there.','stagnate.s2 指水停止流动并逐渐变污浊。','旧水池里的雨水会变脏。')],M('The company began to stagnate by launching new products and expanding into new markets every week.','It stopped developing after its initial growth slowed.','不断创新扩张与停滞相反。','meaning'),[q('Why did the company stagnate?','it lacked new products and customers','it launched products every week','it hired more customers','公司缺少新产品和客户后开始停滞。',1,'context'),q('What may happen to rainwater left in the old basin?','it may stagnate and become dirty','it will flow quickly uphill','it will turn into a library','雨水留在旧池中会停滞变脏。',2,'context'),q('What does stagnate mean about a company?','stop growing or developing','increase rapidly','schedule workers in shifts','stagnate 描述公司时指停止发展。',1,'meaning'),q('What does stagnate mean about water?','stop flowing and become dirty','become a clean current','shock a person','stagnate 描述水时指停止流动并变污。',2,'meaning')]);
P('stagnation','Stagnation comes from Latin stagnare and -tion; it means a prolonged state in which growth, development, or improvement stops.',C('stagnation.s1','停滞；不景气','The region’s economic stagnation lasted several years, with little investment and almost no new hiring.','该地区经济停滞持续了数年，投资很少，几乎没有新增招聘。','The region’s stagnation lasted years / with little investment / and almost no hiring.','stagnation.s1 指事物长期没有发展、增长或改善的状态。','投资和招聘长期低迷。'),M('The region experienced stagnation while new businesses and investment expanded rapidly every month.','The region showed little growth or improvement for several years.','持续迅速扩张与 stagnation 相反。','meaning'),[q('How long did the regional stagnation last?','several years','one afternoon','a single theater performance','该地区经济停滞持续了数年。',1,'context'),q('What was scarce during stagnation?','investment and new hiring','water in the theater','spelling corrections','投资很少，新增招聘也几乎没有。',1,'context'),q('What is stagnation?','a prolonged lack of growth or improvement','a sudden increase in prices alone','a person’s unsteady walk','stagnation 指长期停滞不发展的状态。',1,'meaning'),q('Which economy is in stagnation?','one with little investment and almost no new jobs for years','one adding businesses and jobs rapidly','one that expands every week','多年投资少、几乎不新增岗位的经济处于 stagnation。',1,'context')]);
P('stain','Stain is recorded in Middle English; it can mean leave a difficult-to-remove colored mark, color wood, or a dirty mark/reputational blemish.',[C('stain.s1','沾污；染色','The berry juice stained the white tablecloth, leaving a purple mark that soap could not remove.','浆果汁弄脏了白桌布，留下肥皂也洗不掉的紫色污渍。','The berry juice stained the tablecloth / leaving a purple mark / soap could not remove.','stain.s1 作动词指留下难以除去的颜色，也可指给木材上色。','果汁在桌布留下顽固颜色。'),C('stain.s2','污渍；污点','The audit found no stain on the treasurer’s record after every expense had been checked.','逐项核查开支后，审计没有发现财务主管记录上有任何污点。','The audit found no stain on the record / after every expense / had been checked.','stain.s2 作名词可指污迹，也可比喻损害名誉的污点。','审计未发现不当记录。')],M('Berry juice stained the tablecloth but left no colored mark or trace behind.','The juice left a purple mark that soap could not remove.','没有留下颜色就没有 stain。','meaning'),[q('What stained the tablecloth?','berry juice','a theater spotlight','still water','浆果汁弄脏了桌布。',1,'context'),q('What did the audit find on the treasurer’s record?','no stain','a large unexplained expense','a purple berry mark','审计没有发现财务主管记录上的污点。',2,'context'),q('What does stain mean as a verb?','leave a hard-to-remove colored mark','make water stop flowing','move unsteadily','stain 作动词指留下难洗掉的颜色。',1,'meaning'),q('What can stain mean figuratively?','a mark that harms someone’s reputation','a clean audit','a wooden stair','stain 比喻损害名誉的污点。',2,'meaning')]);
P('stained','Stained is the past participle/adjective of stain; it means discolored by dirt or dye, or treated with a wood stain.',C('stained.s1','有污迹的；着色的','The stained-glass window cast blue and gold shapes across the chapel floor when the morning sun rose.','晨光升起时，彩色玻璃窗把蓝色和金色的光影投在礼拜堂地板上。','The stained-glass window cast colored shapes / across the chapel floor / in morning sun.','stained.s1 可指被污物或染料改变颜色的，也指经着色处理的玻璃或木材。','玻璃经着色后透出彩色光影。'),M('The stained-glass window was completely clear and colorless, casting no colored light.','Colored glass filtered the sunlight into blue and gold shapes.','无色透明玻璃不会投下彩色光影。','meaning'),[q('What colors appeared on the chapel floor?','blue and gold','purple and green','black and white only','彩窗在地板上投下蓝色和金色光影。',1,'context'),q('What made the colored shapes?','morning sun through stained glass','a dirty tablecloth','a stagnant basin','晨光透过彩色玻璃形成光影。',1,'context'),q('What does stained mean about the glass?','colored by treatment','clear and colorless','covered with berry juice','stained glass 指经过着色处理的玻璃。',1,'meaning'),q('Which surface is stained?','a wooden door treated with dark dye','a clear untouched pane','a wall with no color or mark','用深色染料处理的木门是 stained。',1,'context')]);
P('stainless','Stainless combines stain and -less; it means not easily stained or rusted, or figuratively free from blame.',[C('stainless.s1','不锈的；无瑕的','The stainless steel sink resisted rust even after years of daily washing.','这只不锈钢水槽即使每天使用多年也没有生锈。','The stainless steel sink resisted rust / after years / of daily washing.','stainless.s1 指不易沾污或生锈的，也可比喻无可指责的。','金属长期接触水仍抗锈。'),C('stainless.s1','无瑕的；清白的','The investigation left the nurse with a stainless record because every complaint had been disproved.','调查证明每项投诉都不属实，因此护士保持了清白记录。','The investigation left the nurse with a stainless record / after disproving / each complaint.','stainless.s1 也可比喻没有过失或污点。','调查没有发现护士有错。')],M('The stainless steel sink rusted and stained badly after one brief wash.','The sink resisted stains and rust through years of use.','容易生锈和染污与 stainless 相反。','meaning'),[q('What did the sink resist?','rust','daily washing','morning sunlight','水槽长期使用仍能抗锈。',1,'context'),q('Why was the nurse’s record stainless?','the complaints were disproved','the investigation found serious misconduct','the sink had rusted','调查证明投诉不实，护士保持清白记录。',1,'context'),q('What does stainless mean about steel?','not easily stained or rusted','easily covered in rust','treated with colored dye','stainless steel 指不易沾污或生锈的钢。',1,'meaning'),q('What does stainless mean about a record?','free from blame or wrongdoing','made from metal','covered in a purple stain','stainless record 比喻清白无过的记录。',1,'meaning')]);
P('stair','Stair comes from Old English stæger; it means one step in a flight leading from one floor to another.',C('stair.s1','一级楼梯','A loose stair creaked under the visitor’s foot, so the caretaker closed the upper floor for repairs.','访客踩上一阶松动的楼梯时它吱呀作响，因此管理员关闭了楼上区域维修。','A loose stair creaked / under the visitor’s foot / so the floor was closed.','stair.s1 指连接楼层的一组楼梯中的单一级踏步。','有一阶楼梯松动。'),M('The caretaker repaired one stair by replacing the entire building’s roof and removing every step.','The caretaker fixed the loose step in the flight of stairs.','屋顶不是一级楼梯，且拆掉所有台阶不能修好它。','meaning'),[q('What happened when the visitor stepped on the stair?','it creaked','it turned into a window','it stopped the river','松动的楼梯踏步吱呀作响。',1,'context'),q('What did the caretaker close?','the upper floor','the entire town','the theater stage','管理员关闭了楼上区域。',1,'context'),q('What is a stair?','one step in a set leading between floors','the whole structure around the steps','a narrow book edge','stair 指一组楼梯中的一级踏步。',1,'meaning'),q('Which object is a stair?','one tread between the landing and the next step','the complete staircase and its walls','a colored glass window','楼梯平台与下一阶之间的踏步是 a stair。',1,'context')]);
P('staircase','Staircase combines stair and case; it means a set of stairs and the structure enclosing or surrounding them in a building.',C('staircase.s1','楼梯；楼梯结构','The building’s central staircase curved around an open well and connected all six floors.','建筑中央楼梯围绕挑空井盘旋，连接了全部六层。','The central staircase curved around an open well / and connected / all six floors.','staircase.s1 指一整组楼梯以及建筑内围绕楼梯的结构。','楼梯结构连接多层。'),M('The staircase connected six floors although the building contained no steps or vertical access.','A complete set of stairs linked the floors.','没有台阶或垂直通道不能称为 staircase。','meaning'),[q('How many floors did the staircase connect?','six','one','sixty','中央楼梯连接了六层。',1,'context'),q('What did the staircase curve around?','an open well','the treasurer’s desk','a stained-glass painting','楼梯围绕挑空井盘旋。',1,'context'),q('What is a staircase?','a set of stairs and its surrounding structure','one individual step','a landing with no stairs','staircase 指一整组楼梯及其周围结构。',1,'meaning'),q('Which feature is a staircase?','stairs winding around an open shaft in a building','a single loose tread','a flat corridor between rooms','建筑中围绕竖井盘旋的整组楼梯是 staircase。',1,'context')]);
P('stairs','Stairs is the plural of stair; it means a set of steps inside a building connecting different floors.',C('stairs.s1','楼梯（总称）','The delivery worker carried the boxes up the stairs because the old lift was out of service.','旧电梯停用后，送货员只好把箱子搬上楼梯。','The worker carried boxes up the stairs / because the old lift / was out of service.','stairs.s1 是 stair 的复数，通常指连接楼层的一整组台阶。','箱子沿多级台阶搬运。'),M('The worker carried boxes up the stairs by riding the working elevator and never touching a step.','With the lift unavailable, the worker used the steps to reach the upper floor.','乘坐电梯没有使用 stairs。','meaning'),[q('Why did the delivery worker use the stairs?','the lift was out of service','the staircase had no steps','the boxes were already upstairs','电梯停用，所以送货员走楼梯。',1,'context'),q('What did the worker carry?','boxes','a stained-glass window','a rusty sink','送货员搬着箱子上楼。',1,'context'),q('What does stairs mean?','a set of steps between floors','one separate book spine','a theater worker','stairs 指楼层之间的一组台阶。',1,'meaning'),q('When would someone go up the stairs?','when climbing several steps to another floor','when riding a working elevator','when walking across a flat stage','沿多级台阶前往另一层就是 going up the stairs。',1,'context')]);
P('stairway','Stairway combines stair and way; it means a flight of stairs together with the space around or beside it.',C('stairway.s1','楼梯；阶梯通道','Emergency lights marked the stairway leading from the underground station to the street.','应急灯标出了从地下车站通往街面的楼梯通道。','Emergency lights marked the stairway / from the underground station / to the street.','stairway.s1 指室内或室外一段楼梯及其通道空间。','楼梯通道连接地下站与街道。'),M('The stairway led from the station to the street even though it consisted only of a flat ceiling with no steps.','The marked flight of steps provided a route up from the underground station.','没有台阶的天花板不能构成 stairway。','meaning'),[q('Where did the stairway lead?','from the underground station to the street','from the street to a riverbed','from one theater seat to another','楼梯通道从地下车站通往街面。',1,'context'),q('What marked the stairway?','emergency lights','a purple juice stain','a book title','应急灯标出了楼梯通道。',1,'context'),q('What is a stairway?','a flight of stairs and its surrounding passage','one isolated stair tread','a flat ceiling','stairway 指一段楼梯及其通道。',1,'meaning'),q('Which route is a stairway?','steps and passage connecting a station to street level','a hallway with no stairs between doors','a single step in a room','连接车站与街面的阶梯通道是 stairway。',1,'context')]);
P('stake','Stake comes from Old English staca, “post”; it can mean a pointed post, money/share at risk, or risk/support/claim as a verb.',[C('stake.s1','桩；标桩','The surveyor drove a wooden stake into the field to mark the corner of the new fence.','测量员把一根木桩打进田里，标出新围栏的角点。','The surveyor drove a stake into the field / to mark / the fence corner.','stake.s1 指插入地面或其他材料中的尖头木桩、金属桩。','木桩标记围栏位置。'),C('stake.s2','赌注；股份；利害关系','The founders each had a financial stake in the company, so they shared the risk of its success or failure.','创始人各自在公司中有经济利益，因此共同承担成败风险。','Each founder had a stake in the company / and shared / its risks.','stake.s2 可指押上的钱、企业股份或与结果相关的利益。','创始人都承担公司成败风险。'),C('stake.s3','以……打赌；用桩支撑；声称','The climbers staked their tent to the frozen ground so strong wind would not carry it away.','登山者把帐篷用桩固定在冻土上，避免被大风吹走。','The climbers staked the tent / to the frozen ground / against strong wind.','stake.s3 作动词可指押注、用桩固定，也可指提出主张。','帐篷用桩钉牢。')],M('The surveyor marked the fence corner with a stake by placing a loose rope across the road instead of a post.','A pointed post driven into the ground marked the fence corner.','松绳不是插入地面的标桩。','meaning'),[q('What did the surveyor mark with the stake?','the corner of a new fence','the company’s balance sheet','a frozen cave ceiling','木桩标出新围栏的角点。',1,'context'),q('What financial interest did the founders share?','a stake in the company','a stake in the field fence','a stake in the cave wall','创始人各自在公司中有经济利益。',2,'context'),q('Why did climbers stake the tent?','to keep it from blowing away','to calculate the company’s shares','to stain the ground','登山者用桩固定帐篷以免被风吹走。',3,'context'),q('What does stake mean as a noun in the company example?','a share or interest in the business','a pointed post in a field','a tent peg driven into frozen ground','公司例句里的 stake 指股份或利益。',2,'meaning')]);
P('stalactite','Stalactite comes from Greek stalaktos, “dripping”; it is an icicle-shaped mineral deposit hanging from a cave ceiling.',C('stalactite.s1','钟乳石','A thin stalactite hung from the cave ceiling where mineral-rich water had dripped for centuries.','一根细长钟乳石悬挂在洞顶，矿物质丰富的水滴在那里流淌了数百年。','A stalactite hung from the cave ceiling / where mineral-rich water / had dripped for centuries.','stalactite.s1 指从洞穴顶部向下生长的冰锥状矿物沉积物。','水滴长期沉积形成下垂矿物。'),M('The stalactite grew upward from the cave floor rather than hanging from the ceiling.','The mineral deposit hung down from the cave roof.','从地面向上生长的是 stalagmite，不是 stalactite。','meaning'),[q('Where did the stalactite hang?','from the cave ceiling','on the cave floor','inside the station stairway','钟乳石悬挂在洞穴顶部。',1,'context'),q('What formed it over time?','dripping mineral-rich water','a wooden stake','a stained glass window','矿物质丰富的水滴长期形成钟乳石。',1,'context'),q('What is a stalactite?','an icicle-shaped deposit hanging from a cave roof','a mound growing up from a cave floor','a post driven into soil','stalactite 指从洞顶下垂的钟乳石。',1,'meaning'),q('Which cave feature is a stalactite?','a mineral point hanging overhead','a mound rising from the ground','a wooden post at the entrance','悬挂在洞顶的矿物尖体是 stalactite。',1,'context')]);
P('stalagmite','Stalagmite comes from Greek stalagma, “a drop”; it is a mineral mound or column built upward from a cave floor by dripping water.',C('stalagmite.s1','石笋','A broad stalagmite rose from the cave floor beneath a point where mineral water dripped from above.','一根粗大的石笋从洞底升起，正上方有矿物水滴落。','A stalagmite rose from the cave floor / beneath a point / where water dripped.','stalagmite.s1 指由滴水沉积形成、从洞底向上生长的矿物柱或石笋。','沉积物在洞底逐渐堆高。'),M('The stalagmite hung from the cave ceiling and grew downward from the roof.','The mineral mound built upward from the cave floor.','从洞顶下垂的是 stalactite；stalagmite 从洞底向上生长。','meaning'),[q('Where did the stalagmite rise from?','the cave floor','the cave ceiling','the field beside a fence','石笋从洞底升起。',1,'context'),q('What happened directly above it?','mineral water dripped from above','the cave roof was painted','a train passed by','矿物水从石笋正上方滴落。',1,'context'),q('What is a stalagmite?','a mineral mound built upward from a cave floor','an icicle-shaped deposit hanging from a roof','a wooden stake','stalagmite 指从洞底向上形成的石笋。',1,'meaning'),q('How can you distinguish a stalagmite from a stalactite?','the stalagmite grows up from the floor','the stalagmite always hangs down from the ceiling','the stalagmite is a piece of wood','stalagmite 从地面向上生长，stalactite 从洞顶向下悬挂。',1,'meaning')]);
P('stale','Stale is recorded in Old English; its earlier history is uncertain. It means no longer fresh to eat, or no longer new or interesting.',[C('stale.s1','不新鲜的；变味的','The stale crackers had lost their crispness after the open packet sat beside the kettle for a week.','开封饼干放在水壶旁一周后失去了酥脆感，变得不新鲜。','The crackers went stale / after the open packet / sat for a week.','stale.s1 指食物不再新鲜、失去原有口感或气味。','饼干受潮失去酥脆。'),C('stale.s2','陈腐的；乏味的','The presenter dropped a stale joke that the audience had heard in every previous lecture.','听众在以往每场讲座里都听过这个陈腐笑话，主持人便把它删掉了。','The presenter dropped a stale joke / that the audience / had heard before.','stale.s2 指想法、故事等不再新鲜或有趣，也可形容因重复而疲倦。','笑话重复多次不再有趣。')],M('The stale crackers were fresh and crisp because they had just come from a sealed oven.','The open packet had sat for a week, leaving the crackers soft and no longer fresh.','刚烤好且酥脆不符合 stale。','meaning'),[q('What happened to the crackers?','they lost their crispness','they became a stalactite','they were served fresh from the oven','饼干失去了酥脆感。',1,'context'),q('Why did the presenter drop the joke?','the audience had heard it repeatedly','it was new to everyone','it was needed to mark a fence','听众以前听过这个笑话，所以主持人删掉了。',2,'context'),q('What does stale mean about food?','no longer fresh and pleasant to eat','freshly baked and crisp','heavily stained with dye','stale 描述食物时指不再新鲜。',1,'meaning'),q('What does stale mean about a joke?','no longer new or interesting','surprisingly large','unsteady to walk','stale 描述笑话时指陈旧乏味。',2,'meaning')]);
P('stalemate','Stalemate originated as a chess term; it means a deadlock where neither side can move or win, or make a process stop progressing.',[C('stalemate.s1','僵局；相持不下','Negotiators reached a stalemate when neither side would change its position on the border crossing.','双方都不肯改变对边境通道的立场，谈判陷入僵局。','Negotiators reached a stalemate / when neither side / changed its position.','stalemate.s1 指双方互相阻挡，谁也无法获胜或继续前进的局面。','双方立场僵持。'),C('stalemate.s2','使陷入僵局','A disagreement over the budget stalemated the committee, and no vote could be scheduled.','预算分歧使委员会陷入僵局，投票也无法安排。','The budget disagreement stalemated the committee / so no vote / could be scheduled.','stalemate.s2 作动词，指使讨论或进程停止推进。','分歧阻断了委员会的进展。')],M('The border talks reached a stalemate because both sides quickly accepted each other’s terms and signed the deal.','Neither side would compromise, so the negotiations could not move forward.','双方接受条件并签约代表谈判取得进展，不是僵局。','meaning'),[q('Why did the border negotiations stall?','neither side changed its position','both sides signed the agreement immediately','the crossing was closed for lunch','双方都不肯改变立场，谈判陷入僵局。',1,'context'),q('What did the budget disagreement do to the committee?','stopped it from scheduling a vote','made the vote happen earlier','painted the staircase','预算分歧使委员会无法安排投票。',2,'context'),q('What is a stalemate?','a deadlock where neither side can progress or win','a sudden rise in prices','a set of stairs between floors','stalemate 指双方都无法推进或获胜的僵局。',1,'meaning'),q('What does it mean to stalemate a process?','make it stop progressing','move it forward quickly','schedule its events at different times','stalemate a process 指使进程停滞。',2,'meaning')]);
P('stalk','Stalk has plant and verb histories from older Germanic forms; its senses include a plant stem, following quietly, or walking stiffly.',[C('stalk.s1','茎；柄','The celery stalk remained crisp after the cook trimmed its leaves and rinsed it under cold water.','厨师修掉叶片并用冷水冲洗后，芹菜茎仍然爽脆。','The celery stalk remained crisp / after the cook / trimmed its leaves.','stalk.s1 指植物的主要茎，或连接叶片、果实的细柄。','芹菜茎是食用的主茎。'),C('stalk.s2','跟踪；潜近','The wildlife photographer stalked the heron quietly from a distance without disturbing its feeding.','野生动物摄影师远远地悄悄跟踪苍鹭，没有打扰它觅食。','The photographer stalked the heron / quietly from a distance / without disturbing it.','stalk.s2 指悄悄跟随人或动物，常带令人不安或非法意味。','摄影师保持距离且不打扰鸟。'),C('stalk.s3','高视阔步地走','The angry customer stalked out of the office, shoulders stiff and footsteps loud.','愤怒的顾客挺着肩膀、踏步响亮地大步走出办公室。','The angry customer stalked out / with stiff shoulders / and loud footsteps.','stalk.s3 指以僵硬、骄傲或愤怒的姿态行走。','肢体动作显出愤怒。')],M('The photographer stalked the heron by chasing it loudly until the bird flew away.','The photographer followed the heron quietly from a distance.','大声追赶惊飞苍鹭不是悄悄跟踪。','meaning'),[q('Which part of the celery stayed crisp?','the stalk','the roots only','the photographer’s camera','芹菜茎仍然爽脆。',1,'context'),q('How did the photographer follow the heron?','quietly from a distance','by shouting and chasing it','by waiting inside an office','摄影师远远地悄悄跟踪苍鹭。',2,'context'),q('How did the angry customer leave?','with stiff shoulders and loud steps','with a relaxed smile and silent feet','by standing in the queue','顾客挺着肩膀、踏步响亮地走出去。',3,'context'),q('What does stalk mean in the heron example?','follow quietly, often without being noticed','a plant’s main stem','walk out in an angry, stiff way','苍鹭例句中的 stalk 指悄悄跟随。',2,'meaning')]);
P('stall','Stall is from Old English steall, “place”; it can mean a market booth, an animal enclosure/front theater seats, or an engine stop/deliberate delay.',[C('stall.s1','货摊；摊位','A fruit seller arranged ripe pears in a stall near the entrance to the market.','水果摊贩把熟梨摆在市场入口附近的摊位上。','A fruit seller arranged pears in a stall / near the entrance / to the market.','stall.s1 指市场里卖东西的桌台或小店。','梨摆在市场摊位上出售。'),C('stall.s2','马厩；隔间；正厅前座','The mare rested in a clean stall while the theater’s front stalls filled with early ticket holders.','母马在干净的马厩里休息，而剧院正厅前排座位坐满了早到的持票者。','The mare rested in a stall / while the theater’s front stalls / filled with guests.','stall.s2 可指一只动物的封闭隔间，也可指剧院靠近舞台的正厅座位。','同句展示马厩和剧院座位用法。'),C('stall.s3','熄火；故意拖延','The car stalled at the junction, and the driver stalled for time while waiting for roadside help.','汽车在路口熄火，司机一边等道路救援，一边故意拖延时间。','The car stalled at the junction / and the driver stalled for time / awaiting help.','stall.s3 指发动机突然停止，也可指故意拖延。','分别呈现车辆熄火和拖延时间。')],M('The market stall was an empty road with no table, goods, or seller.','The seller’s booth displayed fruit near the market entrance.','没有摊位或商品的道路不是 market stall。','meaning'),[q('Where was the fruit stall?','near the market entrance','inside the theater’s lighting booth','at the junction beside the stalled car','水果摊位在市场入口附近。',1,'context'),q('Where did the mare rest?','in a clean animal stall','in the front theater seats','on the market road','母马在干净的马厩里休息。',2,'context'),q('What happened to the car?','its engine stalled at the junction','it accelerated past the junction','it was parked in a theater seat','汽车在路口熄火了。',3,'context'),q('What does stall mean in “stall for time”?','deliberately delay','sell pears in a booth','a horse’s enclosure','stall for time 指故意拖延时间。',3,'meaning')]);
P('stallion','Stallion came through Old French estalon; it means an adult male horse that has not been castrated, often kept for breeding.',C('stallion.s1','公马；种马','The breeder led the stallion into a separate paddock so it could rest before the spring mating season.','饲养员把种马牵进单独的围场，让它在春季繁殖期前休息。','The breeder led the stallion into a paddock / so it could rest / before breeding season.','stallion.s1 指未阉割的成年公马，常用于繁殖。','公马被单独安置在围场。'),M('The breeder called the mare a stallion even though she was an adult female horse.','The stallion was an adult male horse kept for breeding.','成年母马不是 stallion。','meaning'),[q('Where did the breeder lead the stallion?','into a separate paddock','into the front theater stalls','to a market fruit booth','饲养员把种马牵进单独围场。',1,'context'),q('Why was it resting there?','the spring mating season was approaching','the horse had been sold as pears','the breeder wanted to stage a play','它在繁殖季前休息。',1,'context'),q('What is a stallion?','an adult male horse that has not been castrated','an adult female horse','a horse’s small enclosure','stallion 指未阉割的成年公马。',1,'meaning'),q('Which animal is a stallion?','a male horse kept for breeding','a female mare with a foal','a young calf in a pen','用于繁殖的成年公马是 stallion。',1,'context')]);
P('stalls','Stalls is the plural of stall; it can mean the front seats in a theater or small open market booths.',[C('stalls.s1','（剧院）正厅前排座位','The orchestra sounded clear from the stalls, where the audience sat close to the stage.','坐在靠近舞台的正厅前排座位上，观众能清楚听见管弦乐团演奏。','The orchestra sounded clear from the stalls / where the audience / sat near the stage.','stalls.s1 指剧院靠近舞台的正厅座位区。','观众坐在舞台附近听音乐。'),C('stalls.s2','摊位；货摊','At the weekend fair, the stalls sold handmade soap, pottery, and baskets.','周末集市上的摊位出售手工皂、陶器和篮子。','The stalls sold handmade soap / pottery / and baskets at the fair.','stalls.s2 指市场上出售商品的开敞小店或划出的摊位。','集市摊位出售各种手工品。')],M('The audience sat in the theater stalls far behind the stage in the outdoor parking lot.','The stalls were the theater’s front seats close to the stage.','剧院正厅前排座位不会在舞台后方的停车场。','meaning'),[q('Where did the audience sit?','close to the stage in the stalls','behind the theater outside','at the market’s soap booth','观众坐在靠近舞台的正厅座位区。',1,'context'),q('What did the fair stalls sell?','soap, pottery, and baskets','theater tickets only','a horse and a paddock','集市摊位出售手工皂、陶器和篮子。',2,'context'),q('What does stalls mean in the orchestra example?','front theater seats','market booths','horse enclosures','剧院例句里的 stalls 指正厅座位。',1,'meaning'),q('What does stalls mean at the fair?','small open booths where goods are sold','a set of seats near a stage','a car engine that stopped','集市上的 stalls 指出售商品的小摊位。',2,'meaning')]);
P('stamen','Stamen comes from Latin stamen, “thread”; it is the pollen-bearing part of a flower, made of an anther and filament.',C('stamen.s1','雄蕊','The botanist used a hand lens to inspect the stamen and locate the pollen on its anther.','植物学家用放大镜检查雄蕊，并在花药上寻找花粉。','The botanist inspected the stamen / and located pollen / on its anther.','stamen.s1 指花中产生花粉的部分，由花药和花丝组成。','花粉位于花药上。'),M('The botanist called the flower’s green leaf a stamen even though it produced no pollen.','The stamen is the flower part that bears pollen on its anther.','普通叶片不是花的雄蕊。','meaning'),[q('What did the botanist inspect?','the stamen','the market stall','the mare’s paddock','植物学家检查了雄蕊。',1,'context'),q('Where did the botanist locate pollen?','on the anther','on the theater seat','inside a fruit seller’s basket','花粉在花药上。',1,'context'),q('What is a stamen?','the pollen-bearing part of a flower','a flower’s ordinary green leaf','a plant’s main stem only','stamen 指花中产生花粉的部分。',1,'meaning'),q('Which structure belongs to a stamen?','an anther and its filament','a petal and a root hair','a market booth and table','雄蕊由花药和花丝组成。',1,'meaning')]);
P('stamford','Stamford is a proper place name; the English name is historically associated with Old English stan-ford, “stone ford.”',C('stamford.s1','斯坦福德（地名）','The visitors arrived in Stamford, Connecticut, before driving to the university’s lakeside research center.','游客先抵达康涅狄格州的斯坦福德，然后开车前往大学湖畔研究中心。','The visitors arrived in Stamford / before driving / to the lakeside center.','stamford.s1 是地名，常指美国康涅狄格州的斯坦福德市。','专名在句中作目的地。'),M('The travelers arrived in Stamford, Connecticut, by boarding a ship in a city located in England.','They reached the Connecticut city named Stamford and then drove to the center.','句子把康涅狄格州的斯坦福德说成英国城市。','meaning'),[q('Where did the visitors first arrive?','Stamford, Connecticut','a theater in the city','a village beside a cave','游客先抵达康涅狄格州的斯坦福德。',1,'context'),q('Where did they drive afterward?','to the university’s lakeside research center','to the market stall','to the cave’s stalactites','他们之后开车前往大学湖畔研究中心。',1,'context'),q('What kind of word is Stamford here?','a proper place name','a flower part','an animal enclosure','Stamford 在句中是地名专名。',1,'meaning'),q('Which location is named Stamford?','a city in Connecticut','a theater seat section','a cave mineral deposit','康涅狄格州有一座名为 Stamford 的城市。',1,'context')]);
P('stamina','Stamina comes from Latin stamina, plural of stamen; it means physical strength and energy to keep working or moving for a long time.',C('stamina.s1','耐力；持久力','The marathon runner built stamina through long, steady training rather than occasional all-out races.','马拉松选手通过持续长时间训练来增强耐力，而不是偶尔全力冲刺。','The runner built stamina / through long, steady training / rather than brief races.','stamina.s1 指长时间持续活动所需的体力和精力。','耐力来自持久训练。'),M('The runner showed stamina by stopping after the first minute and lacking energy to continue.','The runner developed the strength to keep moving over a long period.','很快停下且无法继续不是 stamina。','meaning'),[q('How did the runner build stamina?','through long, steady training','by sprinting once and never training again','by sitting in the theater','选手通过持续训练增强耐力。',1,'context'),q('What kind of event needs stamina?','a marathon','a one-step stair climb','a brief glance at a flower','马拉松需要持久力。',1,'context'),q('What does stamina mean?','strength and energy to keep going for a long time','a sudden shock','a flower’s pollen-bearing part','stamina 指长时间坚持所需的体力和精力。',1,'meaning'),q('Which athlete has stamina?','one who can maintain effort through a long race','one who stops immediately from fatigue','one who watches a race from the stalls','能在长跑中持续努力的运动员有 stamina。',1,'context')]);
P('stammer','Stammer is of uncertain Germanic origin; as a verb it means speak with difficulty and repeat sounds, and as a noun the tendency to do so.',[C('stammer.s1','口吃；结结巴巴地说','Nervous before the interview, Eli began to stammer and repeated the first sound of his answer.','面试前很紧张的伊莱开始结结巴巴，说答案时重复了第一个音。','Eli began to stammer / repeating the first sound / of his answer.','stammer.s1 作动词指说话困难并重复某些声音。','紧张使他重复起始音。'),C('stammer.s2','口吃','The speech therapist described the child’s stammer as mild and suggested patient practice.','言语治疗师说孩子的口吃较轻，并建议耐心练习。','The therapist described the child’s stammer / as mild / and suggested practice.','stammer.s2 作名词指口吃的倾向或说话障碍。','治疗师评估了口吃程度。')],M('Eli stammered fluently, speaking every phrase smoothly without repeating or hesitating.','Eli repeated the first sound and struggled to begin his answer.','流畅说话且没有重复与 stammer 相反。','meaning'),[q('Why did Eli begin to stammer?','he was nervous before the interview','he had just won a prize','he was arranging staggered appointments','伊莱面试前紧张，所以开始结巴。',1,'context'),q('What did he repeat?','the first sound of his answer','the entire interview schedule','the flower’s scientific name','他重复了答案的第一个音。',1,'context'),q('What does stammer mean as a verb?','speak with difficulty and repeat sounds','speak fluently without hesitation','walk with unsteady steps','stammer 作动词指结巴、重复声音。',1,'meaning'),q('What did the therapist call mild?','the child’s stammer','the horse’s stall','the runner’s stamina','治疗师说孩子的口吃较轻。',2,'context')]);
P('stamp','Stamp comes from Germanic stampen, “to pound”; it can mean a postage mark/tool, tread hard, or attach/mark something.',[C('stamp.s1','邮票；印章；戳记','I put a stamp on the envelope before dropping the letter in the mailbox.','我在信封上贴了邮票，然后把信投进邮箱。','I put a stamp on the envelope / before dropping / the letter in the mailbox.','stamp.s1 可指贴在信件上的小纸片，也可指工具压出的标记。','信封贴上邮票后寄出。'),C('stamp.s2','跺脚；重踩','The impatient child stamped one boot on the floor when the bus was late.','公交车迟到时，焦急的孩子用靴子在地板上跺了一下。','The child stamped one boot / on the floor / when the bus was late.','stamp.s2 指用力把脚踩在地面上。','孩子因等车而跺脚。'),C('stamp.s3','贴邮票；盖章；使带有特征','The clerk stamped the permit with the date and stamped the parcel before dispatch.','职员在许可证上盖上日期章，并在包裹发出前盖章。','The clerk stamped the permit / with the date / before dispatching the parcel.','stamp.s3 作动词可指贴邮票、盖印，或使某物带有某特征。','文件和包裹都被盖章。')],M('I stamped the envelope by placing no postage on it and mailing it without a mark.','I attached a postage stamp before mailing the letter.','没有贴邮票不符合动词 stamp 的邮寄用法。','meaning'),[q('What did the speaker put on the envelope?','a postage stamp','a market price tag','a flower stamen','寄信前在信封上贴了邮票。',1,'context'),q('What did the child do when the bus was late?','stamped a boot on the floor','stamped the permit with a date','stamped a letter into the mailbox','孩子因公交迟到在地板上跺脚。',2,'context'),q('What did the clerk do to the permit?','marked it with the date','tore it into two pieces','sent it without any mark','职员在许可证上盖了日期章。',3,'context'),q('What does stamp mean in the envelope example?','a small postage label','a foot hitting the floor','a date-marking action','信封例句中的 stamp 指邮票。',1,'meaning')]);
P('stampede','Stampede came through Spanish estampida, “uproar”; it means a sudden mass rush of frightened animals or people, or cause such a rush.',C('stampede.s1','狂奔；蜂拥','When the gate opened, a frightened stampede of cattle rushed across the field and broke the fence.','大门打开时，受惊的牛群狂奔穿过田地，撞坏了围栏。','A frightened stampede of cattle rushed across the field / and broke / the fence.','stampede.s1 指受惊动物或人群突然大量奔逃，也可指引发这种奔逃。','受惊牛群集体冲撞围栏。'),M('The cattle stampede moved calmly one at a time in a quiet line without frightening anyone.','The frightened herd rushed together across the field.','平静有序地逐只行走不是 stampede。','meaning'),[q('What animals were involved in the stampede?','cattle','stallions alone at a breeding farm','whales near a cave','受惊的牛群突然狂奔。',1,'context'),q('What did the herd break?','the fence','a theater staircase','a stamped permit','牛群撞坏了围栏。',1,'context'),q('What is a stampede?','a sudden mass rush of frightened animals or people','a slow orderly single-file walk','a long period without economic growth','stampede 指受惊动物或人群突然蜂拥奔逃。',1,'meaning'),q('What might cause a stampede?','a loud crash frightening a crowd of animals','a quiet stable with calm horses','a scheduled race starting on time','突发巨响吓到动物可能引发 stampede。',1,'context')]);
P('stance','Stance came through Italian stanza, “standing/place”; it can mean a publicly stated opinion or the way a person positions their body.',[C('stance.s1','立场；态度','The mayor explained her stance on water conservation at the public meeting.','市长在公开会议上阐明了自己对节水问题的立场。','The mayor explained her stance / on water conservation / at the public meeting.','stance.s1 指公开表达的观点或态度。','市长表明了政策观点。'),C('stance.s2','站姿','The tennis coach adjusted Leo’s stance so he could reach the ball without losing balance.','网球教练调整了利奥的站姿，让他能接到球而不失去平衡。','The coach adjusted Leo’s stance / so he could reach / the ball in balance.','stance.s2 指站立时身体的位置和姿势，尤其用于运动。','教练帮助他改善站姿。')],M('The mayor explained her stance by refusing to state any view about water conservation.','She publicly stated her position on conserving water.','拒绝表达任何观点不是 explain her stance。','meaning'),[q('What issue was the mayor’s stance about?','water conservation','the theater’s front seats','the child’s pronunciation','市长阐述了对节水问题的立场。',1,'context'),q('What did the coach adjust?','Leo’s stance','the mayor’s speech','the fence stake','教练调整了利奥的站姿。',2,'context'),q('What does stance mean in the mayor’s example?','a publicly stated opinion','a way of standing in sport','a set of stairs','市长例句中的 stance 指公开立场。',1,'meaning'),q('What does stance mean in tennis?','the player’s body position while standing','the mayor’s opinion','a market booth','网球例句中的 stance 指运动员站姿。',2,'meaning')]);
P('stand','Stand comes from Old English standan; it can mean be on one’s feet, be located/be in a condition, tolerate, or an opinion/booth/viewing structure.',[C('stand.s1','站；站立','Please stand beside the marked line while the nurse checks your height.','护士测量身高时，请站在标记线旁。','Please stand beside the marked line / while the nurse / checks your height.','stand.s1 指以脚着地直立，或从坐/躺姿起身。','测量身高需要直立。'),C('stand.s2','位于；处于','The old clock tower stands at the corner of Main Street and Harbor Road.','老钟楼位于主街与港湾路的交叉口。','The clock tower stands at the corner / of Main Street / and Harbor Road.','stand.s2 指处于某位置或状态。','钟楼位于两条街交叉口。'),C('stand.s3','忍受','I cannot stand the constant drilling outside my office, so I moved to a quieter room.','我无法忍受办公室外持续不断的钻孔声，于是搬到了更安静的房间。','I cannot stand the constant drilling / outside my office / so I moved.','stand.s3 指容忍不愉快的事物。','说话者无法忍受噪声。'),C('stand.s4','立场；摊位；看台','At the book fair, the charity’s stand offered free maps, and its director took a firm stand for literacy.','书展上，慈善机构的摊位免费提供地图，负责人则坚定支持读写教育。','The charity’s stand offered maps / while its director took a firm stand / for literacy.','stand.s4 可指观点立场，也可指销售摊位或看台。','句子展示摊位和观点立场两种用法。')],M('Please stand beside the line by lying flat on the floor while the nurse checks your height.','Please remain upright beside the line for the height check.','躺平不属于 stand。','meaning'),[q('Where should the patient stand?','beside the marked line','at the clock tower corner','inside the charity stand','请站在标记线旁测量身高。',1,'context'),q('Where does the old clock tower stand?','at the corner of two streets','inside the nurse’s office','on the harbor floor','钟楼位于两条街交叉口。',2,'context'),q('What can the speaker not stand?','constant drilling noise','a marked line','free maps','说话者无法忍受持续钻孔声。',3,'context'),q('What did the charity’s stand offer?','free maps','a quiet room','a clock tower','慈善机构的摊位免费提供地图。',4,'context')]);
P('stand for','Stand for combines stand and for; it can mean represent/denote an abbreviation or idea, or tolerate behavior one rejects.',[C('stand for.s1','代表；表示','On the lab chart, “H₂O” stands for water, the compound tested in the experiment.','实验室图表中，“H₂O”代表实验所检测的水这种化合物。','“H₂O” stands for water / on the lab chart / used in the experiment.','stand for.s1 指缩写或符号代表某名称、概念或事物。','化学式代表水。'),C('stand for.s2','容忍；忍受','The coach will not stand for bullying, and players who harass teammates are removed from practice.','教练不会容忍欺凌，骚扰队友的球员会被请出训练。','The coach will not stand for bullying / and removes players / who harass teammates.','stand for.s2 指容忍或允许自己不赞同的行为。','教练明确禁止欺凌。')],M('In the chart, H₂O stands for a sports team and has no connection to water.','H₂O is the chemical formula that represents water.','H₂O 代表水，不是运动队。','meaning'),[q('What does H₂O stand for?','water','the coach’s practice','a stadium seat','H₂O 代表水。',1,'context'),q('What will the coach not stand for?','bullying','the players arriving early','a chart on the wall','教练不会容忍欺凌。',2,'context'),q('What does stand for mean in the chart?','represent a name or idea','tolerate behavior','stand upright beside a line','图表里的 stand for 指代表某事物。',1,'meaning'),q('What does stand for mean in the coach’s rule?','tolerate or allow','represent a chemical','place an object on a table','教练例句中的 stand for 指容忍或允许。',2,'meaning')]);
P('stand out','Stand out combines stand and out; it can mean be easy to notice because of difference or be much better than others.',[C('stand out.s1','显眼；突出','Her bright yellow coat stood out against the gray coats in the crowded station.','在拥挤车站的灰色外套中，她的亮黄色外套格外显眼。','Her yellow coat stood out / against the gray coats / in the station.','stand out.s1 指因与周围不同而容易被看见或注意。','黄色与灰色形成明显对比。'),C('stand out.s2','脱颖而出；表现突出','Among the finalists, Nia stood out for the clarity of her scientific presentation.','在决赛选手中，妮娅的科学演讲表达清晰，使她脱颖而出。','Nia stood out among the finalists / for the clarity / of her presentation.','stand out.s2 指比同组其他人表现更好或更突出。','她的演讲清晰出色。')],M('The yellow coat stood out in the station because it matched every gray coat exactly.','It was easy to notice because its color contrasted with the gray coats.','完全相同的颜色不会因为对比而显眼。','meaning'),[q('Why was the coat easy to notice?','its bright yellow contrasted with gray coats','it was hidden under all the gray coats','the station had no people','亮黄色外套与灰色外套形成对比。',1,'context'),q('Why did Nia stand out among finalists?','her presentation was clear','her coat was hidden','she left before presenting','妮娅因演讲清晰而脱颖而出。',2,'context'),q('What does stand out mean about the coat?','be easy to notice because it looks different','be better at scientific speaking','tolerate bullying','外套例句中的 stand out 指因不同而显眼。',1,'meaning'),q('What does stand out mean about Nia?','perform much better or more impressively than peers','wear a bright coat','represent a chemical formula','妮娅例句中的 stand out 指表现突出。',2,'meaning')]);
P('standard','Standard comes from Old French estandart, originally a military banner; it can mean a measure of quality or usual/accepted.',[C('standard.s1','标准；水平；规范','The laboratory uses the same safety standard for every chemical storage cabinet.','实验室对每个化学品储存柜都采用相同的安全标准。','The laboratory uses one safety standard / for every chemical cabinet / in the building.','standard.s1 指用来衡量质量或要求的水平、规范。','同一规范用于所有柜子。'),C('standard.s2','标准的；普通的','The hotel provides standard rooms with a desk and private bathroom, while larger suites cost extra.','酒店提供配有书桌和独立浴室的标准客房，较大的套房则需额外付费。','The hotel provides standard rooms / with a desk and bathroom / while suites cost extra.','standard.s2 作形容词指通常、普遍接受或非特殊的。','标准客房与额外收费套房对比。')],M('The lab’s safety standard allowed every cabinet to ignore storage rules and use no precautions.','The standard specified the same safety requirements for all cabinets.','没有任何安全要求不是 safety standard。','meaning'),[q('What used the same safety standard?','every chemical storage cabinet','the hotel’s suites only','the station’s coats','实验室所有储存柜采用相同安全标准。',1,'context'),q('What did standard hotel rooms include?','a desk and private bathroom','a swimming pool in every room','a laboratory cabinet','标准客房配有书桌和独立浴室。',2,'context'),q('What does standard mean as a noun?','a level or rule used to measure quality','an unusual luxury room','a theater employee','standard 作名词指衡量质量的标准。',1,'meaning'),q('What does standard mean about the hotel room?','usual and accepted rather than special','a formal safety requirement','an outstanding performance','standard 描述客房时指普通常规的。',2,'meaning')]);
P('standardization','Standardization is formed from standardize and -ation; it means applying uniform standards to products, tests, or procedures.',C('standardization.s1','标准化','Standardization of the test format allowed scores from different schools to be compared fairly.','考试形式标准化后，不同学校的分数得以公平比较。','Standardization of the test format / allowed scores / to be compared fairly.','standardization.s1 指让产品、测试或流程采用统一标准。','统一考试形式使成绩可比。'),M('The school’s standardization made every test use a different format and scoring scale.','The schools used one common test format and scoring method.','不同格式和尺度不是标准化。','meaning'),[q('What did standardization make comparable?','scores from different schools','the coats at the station','the size of a cave','标准化使不同学校的成绩可比较。',1,'context'),q('What was made uniform?','the test format','each school’s students','the number of chemistry cabinets','考试形式采用统一标准。',1,'context'),q('What is standardization?','applying uniform standards to procedures or products','making each procedure completely different','a person’s public standing','standardization 指对流程或产品统一标准。',1,'meaning'),q('Which policy is standardization?','all branches use the same forms and scoring rules','each branch invents separate test rules','no branch records any score','所有分支使用同一表格和评分规则属于 standardization。',1,'context')]);
P('standardize','Standardize combines standard and -ize; it means make different products, methods, or names follow one fixed standard.',C('standardize.s1','使标准化；统一规格','The hospital will standardize its intake forms so every clinic records the same patient information.','医院将统一登记表格式，让每家诊所记录相同的患者信息。','The hospital will standardize its forms / so every clinic / records the same information.','standardize.s1 指使不同产品、方法或名称遵循统一标准。','统一表格使记录项目一致。'),M('The hospital standardized its forms by giving each clinic a different layout and incompatible fields.','It adopted one shared form layout and common data fields.','各诊所互不兼容的表格不是标准化。','meaning'),[q('What will the hospital standardize?','its intake forms','its patient names','its theater seats','医院将统一登记表格式。',1,'context'),q('What will each clinic record?','the same patient information','a different set of unrelated fields','the clinic’s coat colors','每家诊所会记录相同的患者信息。',1,'context'),q('What does standardize mean?','make things follow one fixed standard','give every item a different rule','remove every measurement','standardize 指使事物遵循统一标准。',1,'meaning'),q('Which action standardizes a process?','requiring every branch to use the same procedure','letting each branch invent incompatible steps','stopping all record keeping','要求所有分支使用相同流程是在 standardize。',1,'context')]);
P('standardized','Standardized is the past participle/adjective of standardize; it means brought into conformity with a common standard.',C('standardized.s1','标准化的','The standardized report used the same headings and units at all twelve research sites.','这份标准化报告在全部十二个研究点都使用相同标题和计量单位。','The standardized report used common headings / and units / at all twelve sites.','standardized.s1 指已经按统一标准调整、彼此可对应的。','各地点采用统一格式。'),M('The report was standardized even though every site used unrelated headings and measurement units.','All research sites followed one format with the same headings and units.','彼此无关的格式不是 standardized。','meaning'),[q('How many research sites used the standardized report?','twelve','two','one hundred and twelve','十二个研究点使用统一格式。',1,'context'),q('What matched across all the sites?','headings and measurement units','researchers’ personal opinions','the color of every building','各地点的标题和计量单位一致。',1,'context'),q('What does standardized mean?','brought into conformity with a common standard','left different at every location','made difficult to compare','standardized 指按共同标准统一过的。',1,'meaning'),q('Which dataset is standardized?','records from every site use matching fields and units','each site labels the same field differently','all measurements are missing','各地点字段和单位一致的数据集是 standardized。',1,'context')]);
P('standby','Standby combines stand and by; it can mean a person/thing ready if needed or ready as a backup.',[C('standby.s1','备用物；待命人员','A standby technician waited near the control room in case the main operator became ill.','一名待命技术员在控制室附近等候，以防主要操作员生病。','A standby technician waited nearby / in case the main operator / became ill.','standby.s1 指需要时可以顶替的人或备用物。','技术员处于待命状态。'),C('standby.s2','备用的','The clinic kept a standby generator ready to power its vaccine refrigerator during outages.','诊所备有一台备用发电机，以便停电时为疫苗冰箱供电。','The clinic kept a standby generator / ready to power / the vaccine refrigerator.','standby.s2 作形容词，指主设备故障时可立即使用的备用设备。','发电机用于停电备用。')],M('The standby generator was unavailable during the outage because the clinic had no backup equipment.','The clinic kept a ready backup generator for power failures.','没有备用设备与 standby generator 相反。','meaning'),[q('Where did the standby technician wait?','near the control room','inside the vaccine refrigerator','at the market stall','待命技术员在控制室附近等候。',1,'context'),q('What would the standby generator power?','the vaccine refrigerator','the theater audience','the clinic’s staircase','备用发电机为疫苗冰箱供电。',2,'context'),q('What is a standby technician?','a worker ready to step in if needed','the main operator already at work','a person who wrote the safety standard','standby technician 指随时可以顶替的人员。',1,'meaning'),q('What does standby mean about the generator?','available as a backup','the main source already running','unable to start','standby generator 指可随时启用的备用发电机。',2,'meaning')]);
P('standing','Standing is formed from stand and -ing; it can mean a person’s rank or reputation, or continuing/long-lasting.',[C('standing.s1','地位；名望','The professor’s standing in the scientific community grew after her careful work was cited by many researchers.','这位教授严谨的研究被许多学者引用后，她在科学界的声望提高了。','The professor’s standing grew / after her work / was widely cited.','standing.s1 指个人或组织在群体中的尊重、地位或声誉。','研究成果提升了她的声望。'),C('standing.s2','常设的；长期有效的','The committee has a standing rule that every expense over $500 must be approved in writing.','委员会有一项长期有效的规定：每笔超过500美元的开支都必须书面批准。','The committee has a standing rule / requiring written approval / over $500.','standing.s2 作形容词，指持续或长期有效的。','规则不是临时制定的。')],M('The committee’s standing rule applied only once and expired immediately after that single expense.','The rule remained in force for all qualifying expenses over time.','只适用一次且立刻失效不是 standing rule。','meaning'),[q('Why did the professor’s standing grow?','many researchers cited her careful work','she canceled every study','the committee approved a purchase','许多学者引用她的研究，提高了教授的声望。',1,'context'),q('When must large expenses be approved?','every expense over $500','only the first expense ever','no expense needs approval','每笔超过500美元的开支都要批准。',2,'context'),q('What does standing mean about the professor?','her rank or reputation in the community','a posture at a tennis match','a rule that ended yesterday','standing 描述教授时指她的声望。',1,'meaning'),q('What does standing mean in “a standing rule”?','continuing or long-lasting','a person’s public reputation','a table in a market','standing rule 指长期有效的规定。',2,'meaning')]);
P('standpoint','Standpoint combines stand and point; it means a particular way of considering or judging an issue.',C('standpoint.s1','立场；观点','From a public-health standpoint, the town’s new bike lanes could reduce traffic injuries.','从公共卫生角度看，镇上新建的自行车道可能减少交通伤害。','From a public-health standpoint / the new bike lanes / could reduce injuries.','standpoint.s1 指观察、理解或评判问题的特定角度。','句首短语限定讨论问题的角度。'),M('From a public-health standpoint, the planner refused to consider health or safety at all.','The planner considered the issue from the perspective of public health.','完全不考虑健康和安全就不是从公共卫生角度出发。','meaning'),[q('From what standpoint did the planner assess the bike lanes?','public health','the theater’s ticket sales','a ship’s starboard side','规划者从公共卫生角度评估自行车道。',1,'context'),q('What could the new lanes reduce?','traffic injuries','stanzas in a poem','the price of a meal','新车道可能减少交通伤害。',1,'context'),q('What does standpoint mean?','a particular way of considering an issue','a ship’s right side','the first part of an activity','standpoint 指看待问题的特定角度。',1,'meaning'),q('Which question asks for someone’s standpoint?','“From which perspective do you judge this policy?”','“How many wheels does the bicycle have?”','“Where is the ship’s kitchen?”','询问评判政策的角度是在问对方的 standpoint。',1,'meaning')]);
P('standstill','Standstill combines stand and still; it can mean complete stopping of movement/activity or a period in which progress ceases.',[C('standstill.s1','停顿；完全停止','After a truck blocked both lanes, traffic came to a standstill on the bridge.','一辆卡车堵住两条车道后，桥上的交通完全停了下来。','Traffic came to a standstill / after a truck / blocked both lanes.','standstill.s1 指车辆、机器或活动完全停下、不再移动。','两条车道被堵使车辆停止。'),C('standstill.s2','停滞；无进展的时期','Talks remained at a standstill for weeks because the two teams would not revise their offers.','由于双方都不肯修改报价，谈判数周毫无进展。','Talks remained at a standstill / for weeks / because offers were unchanged.','standstill.s2 指某件事停止发展、长期没有进展的一段时间。','谈判没有向前推进。')],M('Traffic came to a standstill as cars crossed the bridge quickly without interruption.','The blocked lanes stopped traffic completely.','车辆持续快速通行不是 standstill。','meaning'),[q('What caused traffic to stop?','a truck blocked both lanes','a car left the bridge','a poem ended','卡车堵住两条车道，交通停了下来。',1,'context'),q('How long did the talks remain stalled?','for weeks','for a few seconds only','until both sides revised their offers','谈判数周毫无进展。',2,'context'),q('What does standstill mean about the traffic?','complete stopping of movement','a period of negotiation with no progress','a sudden surprise','交通例句中的 standstill 指完全停止。',1,'meaning'),q('What does standstill mean about the talks?','a period with no development or progress','a bridge blocked by a truck','a fixed look at a speaker','谈判例句中的 standstill 指停滞不前。',2,'meaning')]);
P('stanza','Stanza comes from Italian stanza, “room” or “stopping place”; in poetry it is a group of lines forming a unit, often separated by a blank line.',C('stanza.s1','诗节','The poet left a blank line between each stanza so readers could pause before the next image.','诗人在每个诗节之间空一行，让读者读到下一个意象前可以停顿。','The poet left a blank line / between each stanza / so readers could pause.','stanza.s1 指诗歌中构成一个单元的一组诗行，通常与下一组分开。','空行标出诗节边界。'),M('The poem’s stanza was one continuous line with no grouped lines or separation.','Each stanza grouped several lines and was set apart by a blank line.','没有分组或分隔的一整行不是 stanza。','meaning'),[q('What separated the stanzas?','a blank line','the bridge’s two lanes','a market table','诗节之间有空行。',1,'context'),q('Why did the poet leave a blank line?','to give readers a pause before the next image','to mark the poem’s price','to stop the truck on the bridge','空行让读者在下一个意象前停顿。',1,'context'),q('What is a stanza?','a group of poem lines forming one unit','a single unrelated word','a theater’s front seating area','stanza 指构成诗歌单元的一组诗行。',1,'meaning'),q('How are stanzas often distinguished?','by a blank line separating each group','by a bridge crossing every line','by printed prices after each line','诗节通常由空行与下一组诗行区分。',1,'meaning')]);
P('staple','Staple is recorded in Middle English with senses linked to a principal commodity and a fastening device; it can mean a main food/product, a wire fastener, or be a verb/adjective.',[C('staple.s1','主食；主要产品；基本要素','Rice is a staple in the region, served at most family meals throughout the year.','米饭是当地的主食，一年中大多数家庭餐食都会供应。','Rice is a staple in the region / served at family meals / throughout the year.','staple.s1 指主要食物、产品或经常出现的基本要素。','米饭经常作为主食。'),C('staple.s2','订书钉','A bent staple remained in the report after the assistant removed the old cover.','助理取下旧封面后，报告上还留着一枚弯曲的订书钉。','A bent staple remained in the report / after the cover / was removed.','staple.s2 指用来固定纸张的小段弯曲金属丝。','订书钉留在纸页上。'),C('staple.s3','主要的；基本的','Fresh vegetables are a staple part of the school lunch menu.','新鲜蔬菜是学校午餐菜单中的基本部分。','Fresh vegetables are a staple part / of the school lunch menu / each week.','staple.s3 作形容词，指主要、常见或基本的。','蔬菜常规出现在午餐菜单上。'),C('staple.s4','用订书钉订','The clerk stapled the receipts together before filing them by date.','职员把收据订在一起，再按日期归档。','The clerk stapled the receipts together / before filing them / by date.','staple.s4 作动词，指用订书钉固定纸张。','收据被订在一起。')],M('Rice was not a staple in the region because it was never eaten and was absent from every meal.','Rice was a main food served regularly at family meals.','完全不食用的食物不能称为当地 staple。','meaning'),[q('What food was a staple in the region?','rice','a bent metal fastener','a poem stanza','米饭是当地的主食。',1,'context'),q('What remained in the report?','a bent staple','a grain of rice','a bus ticket','报告上留下了一枚订书钉。',2,'context'),q('What did the clerk do to the receipts?','stapled them together','served them at lunch','set them apart as poem lines','职员把收据订在一起。',4,'context'),q('What does staple mean as an adjective?','main and standard','a metal fastener','a verb for joining papers','staple 作形容词指主要、基本的。',3,'meaning')]);
P('star','Star comes from Old English steorra; it can mean a luminous celestial body, a famous performer/main actor, or perform as a leading actor.',[C('star.s1','星；恒星','A bright star appeared above the eastern ridge shortly after the sun went down.','太阳落山后不久，一颗明亮的星星出现在东边山脊上空。','A bright star appeared / above the eastern ridge / after sunset.','star.s1 指夜空中看见的由炽热气体构成的大型天体。','夜空中的亮点是恒星。'),C('star.s2','明星；主角','The film’s star greeted fans outside the theater after the premiere.','电影首映后，主演在剧院外向粉丝致意。','The film’s star greeted fans / outside the theater / after the premiere.','star.s2 指著名表演者或电影中的主要演员。','主演在首映后与粉丝见面。'),C('star.s3','主演；担任主角','Two young actors will star in the school’s production of the comedy next month.','两名年轻演员将于下月在学校的喜剧演出中担任主演。','Two young actors will star / in the school comedy / next month.','star.s3 作动词，指在电影或演出中担任主要角色。','演员将担任学校戏剧的主角。')],M('The film’s star was the person who watched from the audience and had no role in the movie.','The star was the main actor who greeted fans after the premiere.','观众不是电影主演。','meaning'),[q('Where did the bright star appear?','above the eastern ridge','inside the theater lobby','on the lunch menu','明亮的星出现在东边山脊上空。',1,'context'),q('Who greeted fans after the premiere?','the film’s star','the truck driver','the poet','电影主演在首映后向粉丝致意。',2,'context'),q('What will the two young actors do?','star in the school comedy','watch the play from the audience','write a blank line between stanzas','两名年轻演员将在学校喜剧中担任主角。',3,'context'),q('What does star mean as a verb?','perform in one of the main roles','shine as a ball of gas only','watch a performance','star 作动词指担任主要角色。',3,'meaning')]);
P('starboard','Starboard is from Old English stēorbord, “steering side”; it means the right-hand side of a ship or aircraft when facing forward.',C('starboard.s1','右舷','The captain ordered the crew to secure the loose rope on the starboard side of the ship.','船长命令船员固定船右舷松脱的绳索。','The captain ordered the crew / to secure the rope / on the starboard side.','starboard.s1 指面向船头或机头时的右侧。','绳索位于船只右侧。'),M('The captain called the ship’s left side starboard while facing forward.','Starboard is the right-hand side when facing the front.','面向前方时左侧是 port，不是 starboard。','meaning'),[q('Where was the loose rope?','on the starboard side','on the roof of the theater','beneath the cave floor','松绳在船只右舷。',1,'context'),q('What did the captain order the crew to do?','secure the loose rope','move it to a theater stall','leave it trailing behind the ship','船长命令船员固定松绳。',1,'context'),q('Which side is starboard?','the right-hand side when facing forward','the left-hand side when facing forward','the bottom of a ship','starboard 指面向前方时的右侧。',1,'meaning'),q('Where is starboard on an aircraft?','to the pilot’s right when facing forward','behind the tail only','on the floor below the cabin','面向机头时飞行员右侧是 starboard。',1,'meaning')]);
P('starch','Starch is from Old English stearc, “stiff”; it can mean a white energy-giving powder in foods or treat cloth to make it stiff.',[C('starch.s1','淀粉','Potatoes and rice contain starch, which the body can use as a source of energy.','土豆和米饭含有淀粉，人体可以利用它获取能量。','Potatoes and rice contain starch / which the body / can use for energy.','starch.s1 指存在于面包、米饭和土豆等食物中的白色能量性粉末。','食物中的淀粉可供身体利用。'),C('starch.s2','给衣物上浆','Before ironing the uniform, the cleaner starched its collar so the fabric would stay crisp.','熨制服前，洗衣工给衣领上浆，让布料保持挺括。','The cleaner starched the collar / before ironing / so the fabric stayed crisp.','starch.s2 作动词，指用浆液处理布料使其挺括。','衣领经上浆变硬挺。')],M('The cleaner starched the collar by soaking it in a liquid that made the fabric softer and limp.','The starch treatment stiffened the collar before ironing.','使衣料变软无力与 starch 的上浆义相反。','meaning'),[q('Which foods were named as containing starch?','potatoes and rice','fish and berries only','paper and steel','土豆和米饭含有淀粉。',1,'context'),q('What did the cleaner starch?','the uniform’s collar','the theater’s front seats','the ship’s loose rope','洗衣工给制服衣领上浆。',2,'context'),q('What is starch in the food example?','a powder in foods that supplies energy','a wire fastener for paper','a ship’s right side','食物例句中的 starch 指可供能量的淀粉。',1,'meaning'),q('What does starch mean as a verb?','treat cloth to make it stiff','add a powder to a poem','tie a rope on the right side','starch 作动词指给布料上浆使其挺括。',2,'meaning')]);
P('starchy','Starchy combines starch and -y; it can mean containing much starch or overly formal and stiff in behavior.',[C('starchy.s1','淀粉多的','The dietitian suggested replacing some starchy potatoes with leafy greens at dinner.','营养师建议晚餐把一部分淀粉含量高的土豆换成绿叶蔬菜。','The dietitian suggested replacing starchy potatoes / with leafy greens / at dinner.','starchy.s1 指含淀粉多的食物。','土豆被归为淀粉类食物。'),C('starchy.s1','拘谨的；过分正式的','The host’s starchy manners made the casual picnic feel like a formal banquet.','主人过分拘谨的举止，让轻松野餐变得像正式宴会。','The host’s starchy manners / made a casual picnic / feel like a banquet.','starchy.s1 也可形容举止过分正式、僵硬。','人的行为显得不自然拘谨。')],M('The dietitian called the leafy greens starchy even though they contained no starch and were all fiber.','The dietitian identified potatoes as the high-starch food.','不含淀粉的绿叶菜并非 starchy 食物。','meaning'),[q('What did the dietitian suggest replacing?','some potatoes','the picnic host','a poem’s stanza','营养师建议替换一部分土豆。',1,'context'),q('What made the picnic feel like a banquet?','the host’s stiff manners','the leafy greens','the weather forecast','主人的拘谨举止让野餐显得像宴会。',1,'context'),q('What does starchy mean about potatoes?','containing a lot of starch','overly formal in behavior','a right-hand ship side','starchy 描述土豆时指淀粉多。',1,'meaning'),q('What does starchy mean about the host’s manners?','overly formal and stiff','high in dietary fiber','bright like a star','starchy 描述举止时指拘谨、过分正式。',1,'meaning')]);
P('stardom','Stardom is formed from star and -dom; it means the state of being a celebrated performer in entertainment or sport.',C('stardom.s1','明星身份','The singer’s stardom grew after her first album topped the charts and sold out a national tour.','这位歌手的首张专辑登上排行榜榜首并使全国巡演售罄后，她的明星地位不断上升。','The singer’s stardom grew / after the album topped charts / and the tour sold out.','stardom.s1 指在娱乐或体育领域成为广受赞誉的明星身份。','专辑成功和巡演售罄带来声望。'),M('The singer’s stardom declined because nobody recognized her work and every concert was canceled.','Her successful album and sold-out tour increased her fame.','无人知晓且演出取消与 stardom 上升不符。','meaning'),[q('What happened to the singer’s first album?','it topped the charts','it was never released','it was a standard report','歌手的首张专辑登上排行榜榜首。',1,'context'),q('What happened to the national tour?','it sold out','it was canceled in every city','it took place in a cave','全国巡演门票售罄。',1,'context'),q('What does stardom mean?','the state of being a celebrated entertainer or athlete','one bright object in the night sky','the main part of a poem','stardom 指成为受赞誉明星的身份。',1,'meaning'),q('Which achievement could lead to stardom?','a hit album and a sold-out tour','an unreleased song nobody hears','a quiet walk to the theater','热门专辑和售罄巡演可能带来 stardom。',1,'context')]);
P('stare','Stare comes from Old English starian; it can mean look for a long time with eyes wide open or a long fixed look.',[C('stare.s1','盯着看；凝视','The child stared at the glass frog in the museum case, amazed by its bright blue feet.','孩子惊讶地盯着展柜里的玻璃青蛙，看它鲜蓝色的脚。','The child stared at the glass frog / amazed by / its blue feet.','stare.s1 作动词指睁大眼睛长时间看。','孩子注视展品很久。'),C('stare.s2','凝视','A long stare from the guard made the visitor realize that photography was not allowed.','警卫久久凝视着访客，让访客意识到这里不允许拍照。','A long stare from the guard / made the visitor realize / photos were forbidden.','stare.s2 作名词指长时间固定的目光。','警卫的目光提醒访客。')],M('The child stared at the frog by glancing at it for a fraction of a second and looking away.','The child looked at the display for a long time with wide eyes.','一瞥后立刻移开目光不是 stare。','meaning'),[q('What did the child stare at?','the glass frog','the guard’s uniform','a market stall','孩子盯着玻璃青蛙看。',1,'context'),q('What did the guard’s long stare communicate?','photography was forbidden','the museum was closing next year','the frog was for sale','警卫的凝视让访客意识到不能拍照。',2,'context'),q('What does stare mean as a verb?','look for a long time with eyes wide open','glance briefly and look away','make an image brighter','stare 作动词指长时间盯着看。',1,'meaning'),q('What is a stare?','a long fixed look','a bright star','a short poem section','stare 作名词指凝视。',1,'meaning')]);
P('starfish','Starfish combines star and fish; it is a marine animal, usually with five arms, living on the seabed.',C('starfish.s1','海星','A red starfish clung to the tide pool rock after the water receded.','潮水退去后，一只红色海星仍附着在潮池岩石上。','A red starfish clung to the tide pool rock / after the water / receded.','starfish.s1 指通常有五条腕、生活在海底的海洋动物。','海星附着在潮池岩石上。'),M('The starfish swam above the seabed on four wings like a bird.','The marine animal clung to a rock in the tide pool.','海星没有翅膀，不会像鸟一样飞翔。','meaning'),[q('What color was the starfish?','red','bright blue','white and gold','潮池岩石上附着一只红色海星。',1,'context'),q('What happened to the water?','it receded','it rose above the theater roof','it became a dry stanza','潮水退去后海星仍附着岩石。',1,'context'),q('What is a starfish?','a marine animal that usually has five arms','a luminous ball of gas in the sky','a type of wooden stake','starfish 指通常有五条腕的海洋动物。',1,'meaning'),q('Where does a starfish live?','on the seabed','in the air above a theater','inside a flower’s anther','starfish 生活在海底。',1,'meaning')]);
P('stark','Stark comes from Old English stearc, “stiff/strong”; it can mean bare, severe, unpleasantly clear, or completely.',[C('stark.s1','严酷的；光秃的；鲜明的','The stark winter landscape had bare trees and a white field with no shelter in sight.','严酷的冬日景象中树木光秃，白色田野上看不到任何遮蔽。','The stark winter landscape had bare trees / and no shelter / in sight.','stark.s1 指景象光秃、严酷或对比清晰得令人不适。','无树叶、无遮蔽的景观显得严酷。'),C('stark.s2','完全地','The village was left stark silent after the last train departed and the station lights went dark.','末班车离开、车站灯光熄灭后，村庄完全安静下来。','The village was stark silent / after the last train / departed.','stark.s2 作副词，表示完全、彻底。','stark 修饰 silent 表示全然寂静。')],M('The stark winter landscape was lush with green leaves and sheltered by a dense forest.','The bare trees and open field created a severe, exposed scene.','繁茂绿叶和浓密遮蔽与 stark landscape 相反。','meaning'),[q('What was the winter landscape like?','bare, with no shelter in sight','lush with green leaves','filled with market stalls','冬日景象树木光秃，田野上没有遮蔽。',1,'context'),q('When did the village become stark silent?','after the last train left and the lights went dark','during a loud concert','when the first train arrived','末班车离开且灯熄灭后，村庄完全安静。',2,'context'),q('What does stark mean about the landscape?','bare or severe','full of trees and shelter','a five-armed sea animal','stark 描述景象时指光秃、严酷。',1,'meaning'),q('What does stark mean in “stark silent”?','completely','unpleasantly bare','slightly noisy','stark silent 表示完全寂静。',1,'meaning')]);
P('starkly','Starkly is formed from stark and -ly; it means in a plain, extreme, or sharply contrasting way.',C('starkly.s1','鲜明地；严酷地','The two budgets differed starkly: one funded village clinics, while the other allocated nothing to health.','两份预算差异鲜明：一份资助村庄诊所，另一份则没有分配任何医疗经费。','The budgets differed starkly / one funded clinics / while the other funded none.','starkly.s1 指以清楚、极端或强烈对比的方式。','两个预算的医疗安排截然不同。'),M('The budgets differed starkly because they funded exactly the same clinics with identical amounts.','One budget supported clinics, while the other allocated no health funds.','完全相同的分配方式没有鲜明差异。','meaning'),[q('What did one budget fund?','village clinics','the theater’s orchestra','a starfish habitat only','一份预算资助村庄诊所。',1,'context'),q('What did the other budget allocate to health?','nothing','the same amount as the first','all funds available','另一份预算没有分配医疗经费。',1,'context'),q('What does starkly mean?','in a sharply contrasting or extreme way','in a mildly uncertain way','like a five-armed animal','starkly 表示差异鲜明或极端。',1,'meaning'),q('Which pair differs starkly?','one report recommends action, the other recommends none','two reports give the same recommendation and figures','two identical copies of one report','一份建议行动、另一份完全不建议的报告差异 starkly。',1,'context')]);
P('starlike','Starlike combines star and -like; it means shaped like a star or shining in the way a star does.',C('starlike.s1','似星的','The garden ornament had a starlike shape with five pointed arms and a bright reflective surface.','这个花园装饰物呈星形，有五个尖角，表面闪闪发亮。','The ornament had a starlike shape / with five pointed arms / and a bright surface.','starlike.s1 指形状像星星，或像星星一样发亮。','五角形状类似星形。'),M('The ornament was starlike even though it was a plain smooth circle with no points or shine.','It had a five-pointed shape and reflective surface.','光滑圆形且不发亮的装饰物不是 starlike。','meaning'),[q('How many pointed arms did the ornament have?','five','two','none; it was a circle','装饰物有五个尖角。',1,'context'),q('What made its surface noticeable?','it was bright and reflective','it was completely matte black','it was covered with starch','表面明亮且会反光。',1,'context'),q('What does starlike mean?','shaped like or shining like a star','moving very slowly','a bird in a large flock','starlike 指形状或光芒像星星。',1,'meaning'),q('Which object is starlike?','a bright five-pointed ornament','a dull smooth disk with no points','a market booth near a street','明亮的五角装饰物是 starlike。',1,'context')]);
P('starling','Starling comes from Old English stær, the bird’s name; it is a medium-sized songbird that often gathers in large flocks.',C('starling.s1','欧椋鸟','A flock of starlings wheeled above the marsh and settled together in the reeds at dusk.','一群欧椋鸟在沼泽上空盘旋，黄昏时一起落在芦苇丛中。','A flock of starlings wheeled above the marsh / and settled / in the reeds at dusk.','starling.s1 指常成群活动的中型雀形目鸣禽。','鸟群在黄昏时落入芦苇。'),M('The starling was a solitary whale that lived beneath the ocean floor.','A starling is a medium-sized bird often seen in flocks.','鲸不是鸟类。','meaning'),[q('Where did the starlings settle?','in the reeds','inside the theater stalls','on a clinic stairway','欧椋鸟黄昏时落在芦苇丛中。',1,'context'),q('How did they move above the marsh?','in a flock, wheeling together','one at a time underground','as a single stationary star','欧椋鸟群在沼泽上空一起盘旋。',1,'context'),q('What is a starling?','a medium-sized bird that often forms flocks','a marine animal with five arms','a large ball of burning gas','starling 指常成群活动的中型鸟类。',1,'meaning'),q('Which sight includes starlings?','many birds settling together in reeds at dusk','one star shining above a ridge','a flower’s pollen-bearing part','黄昏时一群鸟落在芦苇中是 starlings。',1,'context')]);
P('start','Start comes from Old English styrtan, “move suddenly”; it can mean begin an activity, set out/start a machine, jump in surprise, or the beginning point.',[C('start.s1','开始；着手','The committee will start its review after all members receive the final budget.','所有成员收到最终预算后，委员会将开始审查。','The committee will start its review / after all members / receive the budget.','start.s1 指开始一项活动或使某事开始。','审查在预算到齐后开始。'),C('start.s2','出发；启动','We start our journey at dawn, and the driver starts the bus before the passengers board.','我们黎明时出发，乘客上车前司机会先启动巴士。','We start the journey at dawn / and the driver starts the bus / before boarding.','start.s2 可指开始行程，也可指启动机器。','句子展示出发和启动车辆。'),C('start.s3','吃惊一跳','The sudden clap made the sleeping dog start and lift its head.','突然的拍手声把睡着的狗吓了一跳，它抬起头来。','The dog started at the sudden clap / and lifted / its head.','start.s3 指因恐惧或惊讶而突然动一下。','突如其来的声音让狗惊跳。'),C('start.s4','开始；起点','The first start of the race was delayed because rain had soaked the track.','由于雨水浸湿了跑道，比赛的起跑时间被推迟。','The start of the race was delayed / because rain / soaked the track.','start.s4 作名词，指某事开始的时刻或最初部分。','比赛起点时间延迟。')],M('The committee started its review before receiving the final budget, then waited until afterward to begin.','It began the review only after all members received the budget.','在预算到齐前就开始与句意相反。','meaning'),[q('When will the committee start its review?','after all members receive the final budget','before the budget is prepared','after the review has ended','所有成员收到最终预算后，委员会才开始审查。',1,'context'),q('When do the travelers start their journey?','at dawn','after the bus returns at night','when the driver parks it','他们黎明时出发。',2,'context'),q('What made the dog start?','a sudden clap','a warm blanket','the bus starting at dawn','突然的拍手声吓了狗一跳。',3,'context'),q('What was delayed by the wet track?','the start of the race','the committee’s budget','the dog’s sleep','雨水浸湿跑道导致比赛起跑时间延迟。',4,'context')]);
P('starter','Starter is formed from start and -er; it can mean a person/thing that begins an activity, a first course, or a device used to begin a race.',C('starter.s1','启动者；开端','The teacher used a short riddle as a starter to begin the science discussion.','老师用一个简短谜语作为开场，引出科学讨论。','The teacher used a riddle as a starter / to begin / the discussion.','starter.s1 指启动活动的人或事物，也可指一餐的前菜或比赛发令装置。','谜语作为讨论的起点。'),M('The teacher used a starter to end the discussion before it had begun.','The riddle served as an opening prompt for the discussion.','开场提示引出讨论，不是结束讨论。','meaning'),[q('What did the teacher use as a starter?','a short riddle','a long final exam','a starfish','老师用简短谜语作为讨论开场。',1,'context'),q('What activity did it begin?','the science discussion','the theater’s last performance','a bus journey home','谜语引出了科学讨论。',1,'context'),q('What is a starter in this example?','something that begins an activity','the final part of an activity','a ship’s right-hand side','这里 starter 指开启活动的事物。',1,'meaning'),q('Which item is a dinner starter?','a small first course served before the main dish','a dessert eaten after the meal','a tool used to stamp papers','正餐主菜前供应的小份前菜是 starter。',1,'meaning')]);
P('starting','Starting is formed from start and -ing; as a noun it means the point or process when an activity or machine begins.',C('starting.s1','开始；起动','The starting of the backup pump was automatic when the water level reached the red mark.','水位达到红线时，备用泵会自动启动。','The starting of the backup pump was automatic / when the water level / reached the mark.','starting.s1 指活动或设备开始发生、运行的起点或过程。','水位触发泵启动。'),M('The starting of the backup pump occurred while it remained switched off and never began operating.','The pump began operating automatically at the marked water level.','泵一直关闭就没有 starting。','meaning'),[q('What triggered the pump’s starting?','the water level reaching the red mark','the theater’s final curtain','a bird settling in reeds','水位达到红线触发备用泵启动。',1,'context'),q('How did the pump start?','automatically','only by a manual speech','after the water was removed','备用泵会自动启动。',1,'context'),q('What does starting mean here?','the point or process when something begins operating','the end of a machine’s use','a market product','这里 starting 指设备开始运行。',1,'meaning'),q('Which event is the starting of a device?','a backup pump begins running at a set water level','a pump is permanently disconnected','a race reaches the finish line','水位到达设定位置时泵开始运行就是 starting。',1,'context')]);
P('starting at','Starting at is a phrase used to show the lowest price, number, or amount at which something is offered.',C('starting at.s1','（价格等）起始于','The museum’s family tickets are starting at twenty dollars when purchased online.','博物馆的家庭票在线购买时起价为二十美元。','Family tickets are starting at twenty dollars / when purchased / online.','starting at.s1 用于说明最低起始价格、数量或金额。','二十美元是家庭票的起步价。'),M('The museum said tickets were starting at twenty dollars even though twenty dollars was the highest possible price and all tickets cost less.','Twenty dollars was the lowest advertised price for family tickets.','起步价是最低价，不是最高价。','meaning'),[q('What ticket price was given as the starting point?','twenty dollars','two hundred dollars','no price was listed','家庭票起价为二十美元。',1,'context'),q('How could customers buy the tickets at that price?','online','only after entering the theater','by trading a race starter','游客可以在线购买起价二十美元的家庭票。',1,'context'),q('What does starting at indicate?','the lowest price or amount offered','the exact final price for every buyer','a machine beginning to operate','starting at 表示价格或金额的起点。',1,'meaning'),q('A tour is “starting at $45.” What does that mean?','some tours cost $45 or more','every tour costs less than $45','the tour begins at 45 minutes past the hour','starting at $45 表示最低价为45美元，部分选择可能更贵。',1,'meaning')]);
P('startle','Startle is related to start and -le; it means cause someone to move suddenly from surprise or mild fear.',C('startle.s1','使吓一跳；使吃惊','A pigeon startled the librarian when it flapped out from behind the return desk.','一只鸽子从还书台后扑出来，把图书管理员吓了一跳。','A pigeon startled the librarian / when it flapped out / from behind the desk.','startle.s1 指突然使人惊讶或轻微害怕，常令对方猛然一动。','鸽子突然飞出使管理员受惊。'),M('The pigeon startled the librarian by warning her gently in advance and moving slowly into view.','The bird surprised the librarian by appearing suddenly.','提前温和提醒不符合突然惊吓。','meaning'),[q('What startled the librarian?','a pigeon','a quiet poem','a fixed safety standard','一只鸽子把图书管理员吓了一跳。',1,'context'),q('Where did the pigeon appear from?','behind the return desk','from the ship’s starboard side','from the race’s starting line','鸽子从还书台后飞出来。',1,'context'),q('What does startle mean?','cause sudden surprise or mild fear','begin an activity','make prices start at a minimum','startle 指突然使人惊讶或害怕。',1,'meaning'),q('Which event would startle a person?','a balloon pops unexpectedly beside them','a friend announces a visit the day before','a quiet light slowly brightens','旁边气球突然爆响会 startle 一个人。',1,'context')]);
P('startling','Startling is formed from startle and -ing; it means so unexpected or surprising that it makes people jump or stare.',C('startling.s1','令人吃惊的','A startling flash lit the dark corridor when the old fuse suddenly blew.','旧保险丝突然烧断时，一道令人吃惊的闪光照亮了黑暗走廊。','A startling flash lit the corridor / when the fuse / suddenly blew.','startling.s1 指出乎意料到使人惊跳或惊讶的。','突然闪光让人吃惊。'),M('The startling flash was expected, dim, and too familiar to make anyone react.','The sudden bright flash surprised people in the dark corridor.','早已预料且微弱的光不会令人 startled。','meaning'),[q('What lit the dark corridor?','a flash from the blown fuse','the sun at noon','a theater spotlight on stage','保险丝烧断时闪光照亮了走廊。',1,'context'),q('Why was the flash startling?','it happened suddenly and unexpectedly','it had been announced a week earlier','it was too dim to notice','闪光突然出现，令人吃惊。',1,'context'),q('What does startling mean?','so unexpected that it makes people jump or stare','so familiar that nobody notices','slow and gradual','startling 指突然得令人惊跳或惊讶。',1,'meaning'),q('Which sound is startling?','a sudden crash behind someone in a quiet room','a gentle chime announced beforehand','steady rain heard all night','安静房间里身后突然一声巨响是 startling。',1,'context')]);
P('starvation','Starvation is formed from starve and -ation; it can mean life-threatening lack of food or a prolonged period with little/no food.',[C('starvation.s1','挨饿；饿死','The relief group delivered grain to the isolated valley to prevent starvation during the winter.','救援组织在冬季向与世隔绝的山谷运送粮食，以防人们饿死。','The relief group delivered grain / to prevent starvation / during the winter.','starvation.s1 指严重缺粮使人或动物极度虚弱甚至死亡。','运粮是为了避免致命饥饿。'),C('starvation.s2','饥饿状态；长期断粮','Months of starvation during the siege left the town with empty stores and exhausted residents.','围城期间数月断粮，使镇上仓库空空、居民筋疲力尽。','Months of starvation during the siege / left stores empty / and residents exhausted.','starvation.s2 指围困、罢工或极端节食造成的长期少食或无食。','围城造成长期断粮。')],M('The relief group prevented starvation by withholding food from the isolated valley all winter.','It delivered grain so people could survive the winter.','不提供食物会加剧而非避免 starvation。','meaning'),[q('What did the relief group deliver?','grain','stained paper','a train timetable','救援组织向山谷运送粮食。',1,'context'),q('When did the town suffer months of starvation?','during the siege','during a summer festival with full stores','after the relief arrived','镇上在围城期间长期断粮。',2,'context'),q('What can severe starvation cause?','extreme weakness and death','a sudden rise in prices','a fixed look from a guard','严重饥饿可能导致极度虚弱甚至死亡。',1,'meaning'),q('What does starvation mean in the siege example?','a prolonged period with little or no food','a short pause in traffic','a meal served before dinner','围城例句中的 starvation 指长期缺乏食物。',2,'meaning')]);
P('starve','Starve comes from Old English steorfan, “die”; it can mean suffer/die from lack of food or deprive a person or thing of what it needs.',[C('starve.s1','挨饿；饿死','Without emergency supplies, the stranded hikers would starve before the rescue team reached the pass.','如果没有紧急补给，救援队抵达山口前，被困的徒步者就会挨饿。','The hikers would starve / without emergency supplies / before rescue reached the pass.','starve.s1 指因缺少足够食物而受饿或死亡。','食物短缺可能危及生命。'),C('starve.s2','使挨饿；使匮乏','A faulty budget can starve the rural clinic of medicine even when the staff are ready to help.','即使医护人员准备好救治，错误的预算也可能使乡村诊所缺乏药品。','A faulty budget can starve the clinic of medicine / even when staff / are ready to help.','starve.s2 可指不提供某人或某事所需资源，使其匮乏。','诊所缺药而无法充分服务。')],M('The hikers would starve without food although the rescue team delivered abundant meals to them.','The hikers lacked supplies and faced hunger before rescue arrived.','收到充足食物与会挨饿的条件相反。','meaning'),[q('What might happen to the hikers without supplies?','they would starve','they would receive a month of meals','they would run the village clinic','缺少补给时徒步者可能挨饿。',1,'context'),q('What did the faulty budget deprive the clinic of?','medicine','a stagehand','a starboard rope','错误预算使诊所缺少药品。',2,'context'),q('What does starve mean about the hikers?','suffer from too little food','wait at a train station','speak with repeated sounds','starve 描述徒步者时指因缺粮挨饿。',1,'meaning'),q('What does “starve the clinic of medicine” mean?','deprive the clinic of needed medicine','feed clinic staff a large meal','stop the clinic from opening early','starve the clinic of medicine 指使诊所缺少所需药品。',2,'meaning')]);
P('starveling','Starveling combines starve and -ling; it means a person suffering from lack of food or someone who looks extremely thin.',C('starveling.s1','饥民；瘦弱的人','The novel describes the starveling child searching the market for scraps after the harvest failed.','小说描写歉收后，一个饥饿瘦弱的孩子在市场里寻找残羹。','The starveling child searched for scraps / after the harvest / failed.','starveling.s1 指缺乏食物的人，也可形容因饥饿而显得瘦弱的人。','歉收使孩子挨饿。'),M('The starveling child was well-fed, strong, and searching the market only for expensive toys.','The child was weak from hunger and searched for leftover food.','身体强健且饱食与 starveling 相反。','meaning'),[q('What was the child searching for?','scraps of food','a new theater seat','a hospital statement','孩子在市场寻找残羹。',1,'context'),q('What had happened to the harvest?','it had failed','it had produced a record crop','it had been stored in the cave','歉收导致孩子挨饿。',1,'context'),q('What is a starveling?','a person suffering from lack of food','a well-fed athlete','a person who studies statistics','starveling 指缺乏食物、十分瘦弱的人。',1,'meaning'),q('Which child might be called a starveling?','a thin child weakened by hunger','a healthy child who has just eaten','a child waiting at the station','因饥饿而瘦弱的孩子可称为 starveling。',1,'context')]);
P('stash','Stash is recorded in nineteenth-century American English; its deeper origin is uncertain. It can mean hide something or a secret store.',[C('stash.s1','藏起来','The hikers stashed extra water beneath a marked rock so they could retrieve it on the return trip.','徒步者把多余的水藏在一块有标记的岩石下，以便返程时取回。','The hikers stashed extra water / beneath a marked rock / for the return trip.','stash.s1 作动词，指把东西藏在隐蔽处，留待以后使用。','水被藏起来供返程使用。'),C('stash.s2','藏匿的一批东西；储藏处','Police found a stash of stolen watches inside a false drawer in the workshop.','警方在作坊的假抽屉里发现了一批藏匿的赃表。','Police found a stash of stolen watches / inside a false drawer / in the workshop.','stash.s2 作名词指秘密藏起来的一批物品。','手表藏在假抽屉里。')],M('The hikers stashed their water by displaying every bottle openly along the trail for anyone to take.','They hid extra water under a marked rock for later use.','公开摆放且供人取走不是 stash。','meaning'),[q('What did the hikers stash?','extra water','stolen watches','a written statement','徒步者藏起了多余的水。',1,'context'),q('Where did police find the stash?','inside a false drawer','beneath the marked trail rock','at the harbor station','警方在假抽屉里发现藏匿物。',2,'context'),q('What does stash mean as a verb?','put something in a secret place for later','show something openly to everyone','make a formal announcement','stash 作动词指藏起东西留待以后使用。',1,'meaning'),q('What is a stash?','a secret store of items','a public price list','a flower’s pollen part','stash 作名词指秘密藏匿的一批东西。',2,'meaning')]);
P('state','State comes from Latin status, “condition/standing”; it can mean a condition, a country/government/region, say formally, or government-related/ceremonial.',[C('state.s1','状态；状况','The mechanic checked the state of the brakes before allowing the bus to leave the station.','技工检查刹车状况后，才允许巴士离开车站。','The mechanic checked the state of the brakes / before the bus / left the station.','state.s1 指某人或某物在特定时刻的状况。','检查的是刹车当时状况。'),C('state.s2','国家；政府；州','The state funded new rural clinics through taxes collected across the region.','州政府通过征收全地区税款，资助新建乡村诊所。','The state funded rural clinics / through taxes / collected across the region.','state.s2 可指国家、其政府或拥有自治政府的地区。','政府使用税收资助诊所。'),C('state.s3','陈述；声明','The witness stated clearly that she had seen the red truck turn toward the harbor.','证人清楚地陈述，她看见红色卡车转向港口。','The witness stated clearly / that she saw the red truck / turn toward the harbor.','state.s3 作动词指正式说出或写明某事。','证人正式陈述所见。'),C('state.s4','国家的；正式的','The president attended a state dinner where foreign officials discussed the new trade agreement.','总统出席国宴，外国官员在席间讨论新的贸易协定。','The president attended a state dinner / where foreign officials / discussed trade.','state.s4 作形容词指由政府提供、控制或以正式礼仪举行的。','国宴是正式国事活动。')],M('The mechanic checked the state of the brakes by refusing to inspect them and assuming they worked.','The mechanic examined the brakes’ condition before the bus left.','没有检查不能确认状况。','meaning'),[q('What did the mechanic check?','the brakes’ condition','the state government’s border','the witness’s dinner','技工检查了刹车状况。',1,'context'),q('How did the state fund new clinics?','with taxes collected across the region','by selling starfish','by closing every rural clinic','州政府使用地区税收资助诊所。',2,'context'),q('What did the witness state?','she saw a red truck turn toward the harbor','the brakes were made of wood','the president canceled dinner','证人陈述她看见红色卡车转向港口。',3,'context'),q('What was the state dinner?','a formal government event','a brake inspection','a condition of the bus','state dinner 指正式国事宴会。',4,'meaning')]);
P('stately','Stately is formed from state and -ly; it describes something grand, formal, and dignified, including a building, person, or pace.',C('stately.s1','宏伟庄严的','The stately courthouse had broad stone steps, tall columns, and a quiet formal entrance.','这座宏伟庄严的法院有宽阔石阶、高大圆柱和肃穆正式的入口。','The stately courthouse had broad steps / tall columns / and a formal entrance.','stately.s1 指建筑或举止宏伟、庄严、正式而有尊严。','建筑的柱廊和石阶显出庄严气派。'),M('The stately courthouse looked flimsy and informal, with crooked plastic walls and a cramped doorway.','The courthouse was grand, formal, and dignified.','简陋歪斜的建筑与 stately 相反。','meaning'),[q('What architectural features did the courthouse have?','broad stone steps and tall columns','a tiny plastic door','a market stall on the roof','法院有宽阔石阶和高大圆柱。',1,'context'),q('How did its entrance feel?','quiet and formal','crowded and noisy like a stampede','temporary and unfinished','法院入口显得肃穆正式。',1,'context'),q('What does stately mean?','grand, formal, and dignified','small and hurried','covered in food starch','stately 指宏伟、庄严、正式的。',1,'meaning'),q('Which building is stately?','a dignified courthouse with columns and stone steps','a flimsy shed with crooked plastic walls','a temporary booth at a fair','有柱廊和石阶的庄严法院是 stately。',1,'context')]);
P('statement','Statement comes from state and -ment; it can mean a formal expression of fact/opinion, an official announcement, or an account of money owed/paid.',[C('statement.s1','陈述；证词','The witness gave a written statement describing the truck she saw near the station.','证人提交了书面陈述，描述她在车站附近看到的卡车。','The witness gave a written statement / describing the truck / near the station.','statement.s1 指正式表达事实或观点的口头或书面内容。','证人以书面形式叙述所见。'),C('statement.s2','声明；公告','The company released a statement explaining why it had closed the factory.','公司发布声明，解释关闭工厂的原因。','The company released a statement / explaining why / it closed the factory.','statement.s2 指公司、政府或组织发布的正式公告。','组织正式解释决定。'),C('statement.s3','对账单；结算单','Her bank statement listed the rent payment and the remaining balance for the month.','她的银行对账单列出了房租付款和本月剩余余额。','Her bank statement listed the rent payment / and the remaining balance / for the month.','statement.s3 指列出账户已付和应付金额的账单。','银行记录收支和余额。')],M('The bank statement showed no transactions because it was an official company announcement about closing a factory.','The bank statement listed the account’s payments and balance.','工厂公告不是银行账户对账单。','meaning'),[q('What did the witness describe in her statement?','a truck near the station','the factory’s annual profits only','a theater’s seating plan','证人描述了在车站附近看到的卡车。',1,'context'),q('What did the company explain in its statement?','why it closed the factory','how to pay the witness','where the train was parked','公司声明解释关闭工厂的原因。',2,'context'),q('What did the bank statement list?','rent payment and remaining balance','the truck’s color only','the company’s press conference seats','银行对账单列出租金付款和余额。',3,'context'),q('What does statement mean in the bank example?','a record of account payments and balance','a witness’s spoken testimony','an organization’s public announcement','银行例句中的 statement 指账户对账单。',3,'meaning')]);
P('statesman','Statesman combines state and man; it means a wise and respected political leader.',C('statesman.s1','政治家','The statesman urged rival parties to reach a peaceful agreement before the national election.','这位受尊敬的政治家敦促对立政党在全国选举前达成和平协议。','The statesman urged rival parties / to reach a peaceful agreement / before the election.','statesman.s1 指明智且受尊敬的政治领导人。','他以经验促成和平协议。'),M('The statesman was a respected political leader who refused to consider any peaceful agreement.','The leader urged the parties to reach a peaceful settlement.','拒绝考虑和平方案与句中政治家的行动相反。','meaning'),[q('What did the statesman urge the parties to do?','reach a peaceful agreement','cancel the election immediately','stagger their speeches','政治家敦促政党达成和平协议。',1,'context'),q('When should they reach the agreement?','before the national election','after the next century','during a cave tour','他希望政党在全国选举前达成协议。',1,'context'),q('What is a statesman?','a wise and respected political leader','a stagehand at a theater','a person who reports statistical data','statesman 指明智而受尊敬的政治领导人。',1,'meaning'),q('Which person might be called a statesman?','a respected leader who negotiates a peaceful settlement','a market seller who hides a stash','a statistician counting chairs','促成和平解决的受尊敬政治领袖可称 statesman。',1,'context')]);
P('static','Static comes from New Latin staticus, from Greek statikos, “causing to stand”; it can mean not moving/changing or collected electricity/radio noise.',[C('static.s1','静止的；静态的；停滞的','The map displayed static boundaries that did not change when the user selected a different year.','用户选择不同年份时，地图显示的边界仍然固定不变。','The map displayed static boundaries / that did not change / by year.','static.s1 指不移动或不发生变化的。','边界没有随年份变化。'),C('static.s2','静电；静电干扰','A burst of static crackled through the radio when the storm passed over the antenna.','暴风雨经过天线时，一阵静电噪声在收音机里噼啪作响。','A burst of static crackled through the radio / as the storm / passed the antenna.','static.s2 指物体表面积聚的电，也可指无线电中的干扰噪声。','天线受到风暴干扰。')],M('The map’s static boundaries changed every minute whenever the user chose a new year.','The boundaries remained fixed across the selected years.','不断变化与 static 相反。','meaning'),[q('What happened when the map year changed?','the boundaries stayed the same','the entire map turned into a bank statement','the boundaries moved every minute','选择不同年份时地图边界保持不变。',1,'context'),q('What caused the radio static?','a storm passing over the antenna','a blank poem stanza','a theater’s front seats','风暴经过天线时收音机出现静电噪声。',2,'context'),q('What does static mean about the map?','not changing','electrical noise','a political leader','static 描述地图边界时指不变化的。',1,'meaning'),q('What does static mean in the radio example?','electrical interference or crackling noise','a fixed boundary','a written account of payments','收音机里的 static 指电磁干扰噪声。',2,'meaning')]);
P('statical','Statical is a rare variant of static; it describes bodies or forces in equilibrium and not in motion.',C('statical.s1','静态的','The engineer made a statical analysis of the bridge while it was at rest under a fixed load.','工程师在桥梁静止承受固定载荷时，对其进行了静态分析。','The engineer made a statical analysis / while the bridge rested / under a fixed load.','statical.s1 是 static 的少见变体，指物体或力处于平衡、不运动状态。','分析研究静止受力状况。'),M('The engineer called the analysis statical even though the bridge was swinging rapidly under changing forces.','The bridge was at rest under a fixed load during the analysis.','快速摆动且受力不断变化不属于静态平衡。','meaning'),[q('What condition was the bridge in during analysis?','at rest under a fixed load','swinging rapidly in a storm','being moved to a new station','桥梁静止承受固定载荷。',1,'context'),q('What did the engineer analyze?','the bridge’s forces in equilibrium','a starling’s flight','a bank account statement','工程师分析了桥梁的静态受力情况。',1,'context'),q('What does statical mean?','in equilibrium and not in motion','moving very quickly','relating to a country government','statical 指处于平衡且不运动的。',1,'meaning'),q('Which study is statical?','examining a still beam under a constant load','tracking a moving vehicle over time','measuring radio crackle during a storm','分析静止梁在恒定载荷下的状态属于 statical。',1,'context')]);
P('station','Station comes from Latin statio, “standing/place”; it can mean a train/bus stop or service base, a broadcaster, or assign someone to a place.',[C('station.s1','车站；站','The train stopped at the station so passengers could board for the coastal town.','火车在车站停下，让乘客上车前往海滨小镇。','The train stopped at the station / so passengers could board / for the coast.','station.s1 指列车或巴士停靠的地点，也可指某项服务的基地。','乘客在车站上车。'),C('station.s2','电台；电视台','The local radio station broadcast weather warnings throughout the night.','当地电台整夜播报天气警报。','The radio station broadcast warnings / throughout the night / to local listeners.','station.s2 指制作或播送广播、电视节目的机构。','电台向听众播报信息。'),C('station.s3','驻扎；派驻','The agency stationed two engineers at the bridge until the repair work was complete.','维修工作完成前，机构把两名工程师派驻在桥边。','The agency stationed engineers at the bridge / until repairs / were complete.','station.s3 作动词，指派某人在特定地点工作，尤指士兵或工作人员。','工程师被派驻在桥边。')],M('The train arrived at the station but could not stop or let passengers board there.','The station was the place where passengers boarded the train.','列车不停靠就不能在该站上车。','meaning'),[q('Where did the train stop?','at the station','inside the radio studio','under a cave stalagmite','火车在车站停下。',1,'context'),q('What did the radio station broadcast?','weather warnings','a bank account balance','a list of theater seats','电台整夜播报天气警报。',2,'context'),q('Where did the agency station engineers?','at the bridge','on the radio frequency','in the market booth','机构把工程师派驻在桥边。',3,'context'),q('What does station mean in the radio example?','a broadcasting organization','a train stop','the act of assigning workers to a site','radio station 指广播机构。',2,'meaning')]);
P('stationary','Stationary comes from Latin stationarius, “of a fixed position”; it means not moving or changing position.',C('stationary.s1','静止的','The bus remained stationary at the curb while the driver checked the warning light.','司机检查警示灯时，巴士一直停在路沿边没有移动。','The bus remained stationary / at the curb / while the driver checked the light.','stationary.s1 指位置不移动或不改变的。','巴士停在路边。'),M('The bus was stationary while it drove quickly across town without stopping.','The bus stayed in one place at the curb.','快速行驶不属于 stationary。','meaning'),[q('Where did the bus remain?','at the curb','inside the radio station','on the bridge roof','巴士一直停在路沿边。',1,'context'),q('What was the driver checking?','the warning light','the state election','a stamen','司机检查警示灯。',1,'context'),q('What does stationary mean?','not moving or changing position','moving along a road','an official written notice','stationary 指静止、不改变位置的。',1,'meaning'),q('Which object is stationary?','a parked bus with its engine off','a train racing between towns','a spinning starfish toy','停着不动的巴士是 stationary。',1,'context')]);
P('stationery','Stationery comes from stationer, historically a bookseller with a fixed shop; it means writing materials such as paper, pens, and envelopes.',C('stationery.s1','文具','The office ordered stationery—paper, pens, and envelopes—before the new school term began.','新学期开始前，办公室订购了纸张、钢笔和信封等文具。','The office ordered stationery / including paper, pens / and envelopes.','stationery.s1 指书写用品，如纸、笔和信封。','例句列出典型文具。'),M('The office ordered stationery consisting of a train, a radio station, and a bridge.','It ordered paper, pens, and envelopes for office use.','交通工具和地点不是文具。','meaning'),[q('Which stationery did the office order?','paper, pens, and envelopes','a bus, a bridge, and a train','a starfish and a cave rock','办公室订购了纸张、钢笔和信封。',1,'context'),q('When was it ordered?','before the new term','after the term ended','during a radio broadcast','办公室在新学期开始前订购文具。',1,'context'),q('What does stationery mean?','materials used for writing','a place trains stop','a government region','stationery 指书写用品。',1,'meaning'),q('Which items are stationery?','notebooks and envelopes','a pen and a stationary bus','a bridge and a radio tower','笔记本和信封是 stationery。',1,'context')]);
P('statistic','Statistic comes from German Statistik; as a noun it can mean a single numerical fact or the science of collecting and studying numbers.',[C('statistic.s1','统计数字','One statistic in the report showed that 62 percent of commuters used public transport last year.','报告中的一项统计数字显示，去年有62%的通勤者使用公共交通。','One statistic showed / that 62 percent of commuters / used public transport.','statistic.s1 指用数字表示的一条信息。','百分比是一项数据。'),C('statistic.s2','统计学','She took a statistics course to learn how samples can represent a larger population.','她修读统计学课程，学习如何用样本代表更大的人群。','She took a statistics course / to learn how samples / represent a population.','statistic.s2 可指收集、分析数字数据的学科；英语中常用复数 statistics。','课程讲授数据分析方法。')],M('The report’s statistic was “many people,” with no number or measurable figure at all.','It gave a numerical figure: 62 percent of commuters used transit.','没有数字的信息不是 statistic。','meaning'),[q('What proportion used public transport?','62 percent','26 percent','100 percent of drivers','报告显示62%的通勤者使用公共交通。',1,'context'),q('What did the statistics course teach?','how samples can represent a population','how to repair a train station','how to write a poem stanza','课程教授如何用样本代表总体。',2,'context'),q('What is a statistic in the report?','a piece of information expressed as a number','a general feeling with no number','a written stationery list','statistic 指一条数字信息。',1,'meaning'),q('What does statistics mean as a field of study?','collecting and studying numerical data','writing official government statements','designing theater stalls','statistics 可指收集和研究数字的学科。',2,'meaning')]);
P('statistical','Statistical is formed from statistic and -al; it can mean relating to methods for numerical data or shown/measured by figures.',[C('statistical.s1','统计的；统计学的','The team used statistical methods to compare survey responses from three age groups.','团队使用统计方法比较三个年龄组的调查回答。','The team used statistical methods / to compare responses / across three age groups.','statistical.s1 指与收集、整理和研究群体数字数据的方法有关。','不同年龄组的回答通过方法比较。'),C('statistical.s2','基于统计数字的','The statistical difference between the two treatments was small, despite a noticeable change in one patient.','尽管一名患者变化明显，两种疗法之间的统计差异仍然很小。','The statistical difference was small / despite a noticeable change / in one patient.','statistical.s2 指由一组数字测量或显示的，而非单个案例判断。','总体数据差异很小。')],M('The team used statistical methods by comparing opinions without collecting or organizing any data.','They analyzed numerical survey responses across the age groups.','没有收集和分析数据不是 statistical methods。','meaning'),[q('What did the team compare?','survey responses from three age groups','the station’s ticket prices','three types of stationery','团队比较了三个年龄组的调查回答。',1,'context'),q('How large was the statistical difference?','small','larger than every individual result','not measured at all','两种疗法之间的统计差异很小。',2,'context'),q('What does statistical mean in the methods example?','relating to methods of numerical data analysis','a single unmeasured opinion','a type of rail station','statistical methods 指统计数据分析方法。',1,'meaning'),q('What does statistical mean in the treatment example?','shown or measured by a set of figures','judged only from one unusual case','fixed in one position','statistical difference 指由一组数据测量出的差异。',2,'meaning')]);
P('statistically','Statistically is formed from statistical and -ly; it means by the methods or results of statistics.',C('statistically.s1','从统计上看','Statistically, the new reading program improved average scores, although a few students did not improve.','从统计结果看，新阅读项目提高了平均分，尽管少数学生没有进步。','Statistically, the program improved average scores / although a few students / did not improve.','statistically.s1 指依据统计方法或统计结果来看。','总体平均分的变化基于数据分析。'),M('Statistically, the scores improved even though the study collected no data and calculated no results.','The data analysis showed an increase in average scores.','没有数据和计算就不能从统计上得出结果。','meaning'),[q('What improved statistically?','average scores','every student’s score without exception','the number of stationery boxes','统计上看，平均分有所提高。',1,'context'),q('Did every student improve?','no, a few did not','yes, all students improved equally','the study did not include students','少数学生没有进步。',1,'context'),q('What does statistically mean?','by statistical methods or results','in a fixed place','in a formal government ceremony','statistically 指依据统计方法或结果。',1,'meaning'),q('Which claim is made statistically?','a data analysis shows the average increased','one person says the class felt better','scores are guessed without records','通过数据分析得出平均值上升，是 statistically 的判断。',1,'context')]);
P('statistician','Statistician is formed from statistic and -ian; it means someone trained to collect, analyze, and interpret numerical data.',C('statistician.s1','统计学家；统计人员','The statistician checked the survey sample before estimating how many households supported the proposal.','统计人员在估算支持该提案的家庭数量前，先检查了调查样本。','The statistician checked the sample / before estimating / household support.','statistician.s1 指受过训练、负责收集分析并解释数字数据的人。','统计人员检查样本质量。'),M('The statistician estimated public support without collecting or analyzing any numerical information.','The trained analyst examined the survey sample and interpreted its figures.','不收集或分析数据不符合统计人员的专业工作。','meaning'),[q('What did the statistician check?','the survey sample','the theater’s star','the clinic’s stationery order','统计人员检查了调查样本。',1,'context'),q('What did the estimate concern?','how many households supported the proposal','how many stars appeared at dusk','how many stalls were in a theater','估算涉及支持提案的家庭数量。',1,'context'),q('What is a statistician?','someone trained to analyze and interpret numerical data','someone who sells stationery','a political leader','statistician 指分析并解释数字数据的专业人员。',1,'meaning'),q('Which worker is a statistician?','a researcher interpreting survey figures','a stagehand setting a prop','a passenger waiting at a station','解释调查数字的研究人员是 statistician。',1,'context')]);
P('statistics','Statistics comes from German Statistik; it can mean organized numerical information or the branch of mathematics that studies numbers.',[C('statistics.s1','统计数据；统计资料','The city published statistics on bus delays, including the number of late trips each month.','市政府公布了公交延误统计资料，包括每月晚点班次的数量。','The city published statistics on bus delays / including late trips / each month.','statistics.s1 指为呈现群体信息而收集整理的数字。','数据按月记录晚点班次。'),C('statistics.s2','统计学','Statistics helps researchers estimate a population trend from a carefully chosen sample.','统计学帮助研究人员从精心选取的样本估计总体趋势。','Statistics helps researchers estimate a trend / from a carefully chosen sample / of the population.','statistics.s2 指研究数字收集与分析的数学分支。','学科将样本结果用于估计总体。')],M('The city’s statistics on bus delays contained no numbers and were only an unmeasured rumor.','The city collected and arranged numerical records of late trips.','没有数字的传闻不属于 statistics。','meaning'),[q('What did the city publish statistics about?','bus delays','theater stardom','the starboard side','市政府公布了公交延误统计资料。',1,'context'),q('What did the statistics include?','the number of late trips each month','the names of every passenger only','a list of unmeasured rumors','统计资料包括每月晚点班次数量。',1,'context'),q('What does statistics mean in the city example?','organized numerical information','a person trained to study data','a single number only','城市例句中的 statistics 指整理后的数字资料。',1,'meaning'),q('What does statistics mean as a subject?','the mathematical study of collecting and analyzing numbers','a list of theater seats','a formal state dinner','statistics 作学科名指研究数字收集和分析的数学分支。',2,'meaning')]);
P('statuary','Statuary comes from Latin statuarius, “of statues”; it can mean statues collectively or relate to making statues.',C('statuary.s1','雕像总称；雕塑的','The museum’s statuary includes marble figures from several centuries and a bronze horse at the entrance.','博物馆的雕像藏品包括跨越数世纪的大理石人物像，以及入口处的一匹铜马。','The museum’s statuary includes marble figures / from several centuries / and a bronze horse.','statuary.s1 可指一组雕像，也可作形容词表示与雕像制作有关。','句中 statuary 指馆藏雕像群。'),M('The museum’s statuary consisted only of written poems and contained no statues or sculptures.','Its statuary collection included marble figures and a bronze sculpture.','诗歌不是雕像或雕塑。','meaning'),[q('What material were some museum figures made from?','marble','paper and ink','starch and cotton','博物馆藏有大理石人物像。',1,'context'),q('What stood at the entrance?','a bronze horse','a starling flock','a bus station','入口处有一匹铜马雕像。',1,'context'),q('What can statuary mean?','statues collectively or related to making statues','a study of numerical data','a written account statement','statuary 可指一组雕像或与雕像制作有关的。',1,'meaning'),q('Which room contains statuary?','a gallery of marble and bronze sculptures','a room containing only poems and reports','a station with no artwork','陈列大理石和青铜雕塑的展厅里有 statuary。',1,'context')]);
})();
